INSERT INTO public.exam_questions (course_id, idx, text, options, correct, explanation, source) VALUES
('abv', 0, 'Según la Teoría de la Codificación Dual, ¿por qué los videos bien diseñados favorecen el aprendizaje?', '["Porque entretienen a los estudiantes y los mantienen atentos durante más tiempo","Porque activan simultáneamente el canal verbal y el no verbal del cerebro","Porque reducen el trabajo del docente en clase","Porque permiten repetir la información las veces necesarias"]'::jsonb, 1, 'La Teoría de la Codificación Dual (Paivio), base del aprendizaje multimedia de Mayer, plantea que el aprendizaje es más efectivo cuando se activan a la vez el canal verbal (palabras) y el no verbal (imágenes/movimiento). Los videos bien diseñados logran exactamente eso.', 'lesson'),
('abv', 1, 'Un docente quiere mostrar a sus estudiantes cómo realizar una operación matemática paso a paso. ¿Qué tipo de video sería más apropiado?', '["Un documental sobre la historia de las matemáticas","Una animación sobre conceptos abstractos","Un tutorial que muestre el proceso paso a paso","Un screencast de una página web de ejercicios"]'::jsonb, 2, 'Los tutoriales son el formato ideal para mostrar procesos paso a paso, como la resolución de operaciones matemáticas. Su estructura secuencial guía al estudiante desde el inicio hasta el resultado.', 'lesson'),
('abv', 2, '¿Cuál de los siguientes criterios es MENOS relevante al seleccionar un video educativo para clase?', '["La fuente o institución que produjo el video","Que el video tenga muchas vistas y ''me gusta''","Que la información esté actualizada y sea verificable","Que el lenguaje sea adecuado para la edad de los estudiantes"]'::jsonb, 1, 'El número de vistas o ''me gusta'' no garantiza la calidad educativa de un video. Un video puede ser viral por razones de entretenimiento sin ofrecer información correcta o pedagógicamente adecuada. Siempre prioriza la fuente, el rigor y la pertinencia.', 'lesson'),
('abv', 3, '¿Cuál es el principal beneficio pedagógico de hacer pausas durante la reproducción de un video?', '["Permite que los estudiantes descansen y recarguen energía","Transforma la experiencia pasiva de ver en aprendizaje activo","Reduce el tiempo total que el docente necesita para cubrir el tema","Evita que los estudiantes se distraigan con el celular"]'::jsonb, 1, 'Las pausas reflexivas transforman la experiencia pasiva (solo ver) en aprendizaje activo. Al detenerse y preguntar, los estudiantes procesan, conectan y consolidan la información en lugar de simplemente recibirla.', 'lesson'),
('abv', 4, '¿Cuál es la principal ventaja de que un docente cree su propio video educativo frente a usar uno de YouTube?', '["Los videos propios suelen tener mejor calidad que los de internet","El docente puede adaptar el contenido al contexto local y la realidad de sus estudiantes","Los videos propios se pueden reutilizar en varios grados","El ministerio de educación pide que los docentes produzcan su material"]'::jsonb, 1, 'La principal ventaja es la pertinencia contextual: un video propio puede usar ejemplos locales, hablar en el idioma o dialecto familiar, y adaptarse exactamente a lo que los estudiantes de esa comunidad necesitan. Eso no lo puede hacer ningún video internacional.', 'lesson'),
('abv', 5, 'Si tienes que elegir entre mejorar la cámara de tu celular o mejorar el audio de tus videos educativos, ¿qué recomienda la buena práctica?', '["Mejorar la cámara, porque la imagen es lo primero que nota el espectador","Ambos son igualmente importantes y deben mejorarse al mismo tiempo","Mejorar el audio, porque un video con imagen regular pero audio claro funciona bien","Ninguno de los dos: los estudiantes aceptan cualquier calidad si el docente explica bien"]'::jsonb, 2, 'El audio es el factor más crítico en un video educativo. Los espectadores toleran imágenes de menor calidad, pero abandonan un video con audio malo o inaudible. Invierte primero en mejorar el ambiente de grabación para un buen sonido.', 'lesson'),
('abv', 6, 'Un docente pide a sus estudiantes que graben un video explicando el proceso de la fotosíntesis. ¿Qué criterio debería tener más peso en la evaluación?', '["La calidad visual y de audio del video","La duración del video (que cumpla con el tiempo asignado)","La precisión y claridad del contenido explicado","La creatividad del formato elegido"]'::jsonb, 2, 'En la evaluación de videos educativos creados por estudiantes, la precisión y claridad del contenido siempre tiene mayor peso que la producción técnica. El objetivo es evaluar el aprendizaje del tema, no las habilidades de edición.', 'lesson'),
('abv', 7, '¿Cuál es la mejor práctica para compartir videos de YouTube con estudiantes de primaria?', '["Dar acceso libre a YouTube para que cada estudiante busque lo que necesita","Crear listas de reproducción curadas con los videos seleccionados y compartir solo ese enlace","Descargar todos los videos y copiarlos en memorias USB para cada estudiante","Proyectar los videos en clase, sin que los estudiantes tengan acceso al enlace en ningún momento"]'::jsonb, 1, 'Las listas de reproducción curadas permiten compartir recursos seleccionados sin exponer a los estudiantes al algoritmo general de YouTube, que puede recomendar contenido inapropiado. Es la práctica más segura y pedagógicamente organizada.', 'lesson'),
('abv', 8, 'Una docente de primaria quiere usar un video de 18 minutos sobre el ciclo del agua. ¿Qué decisión es más coherente con lo que indica la investigación sobre atención?', '["Proyectarlo completo para no perder información valiosa.","Pedir que lo vean completo en casa antes de la clase.","Seleccionar un fragmento de 3 a 4 minutos y pausarlo para hacer preguntas al grupo.","Ponerlo a mayor velocidad para que quepa en la clase."]'::jsonb, 2, 'En primaria conviene fragmentos breves con pausas; la atención cae con la duración y el video pasivo rinde poco.', 'exam'),
('abv', 9, 'Un docente proyecta un video sin pausas y al final pregunta ''¿qué dijo el video?''. Casi nadie responde con precisión. ¿Qué cambio es más efectivo?', '["Repetir el video y pedir que tomen notas mientras lo ven.","Pedir predicciones antes, pausar en momentos clave y hacer preguntas que inviten a opinar o aplicar.","Dar un resumen escrito antes de proyectar el video.","Evaluar con una prueba larga sobre el video."]'::jsonb, 1, 'Las pausas reflexivas y las preguntas de nivel alto convierten ver en aprender.', 'exam'),
('abv', 10, 'Entre dos videos sobre el mismo tema, uno tiene millones de vistas y música llamativa, y otro tiene pocas vistas pero fuente verificable, explicación clara y subtítulos. ¿Cuál conviene según los criterios del curso?', '["El de más vistas, porque muestra que a los estudiantes les gusta.","El que tenga más efectos visuales para atraer al grupo.","Cualquiera, porque el tema es el mismo.","El de fuente verificable, explicación clara y subtítulos, porque la calidad pedagógica pesa más que la popularidad."]'::jsonb, 3, 'La popularidad es el criterio menos relevante; importan fuente, claridad, ritmo y accesibilidad.', 'exam'),
('abv', 11, 'Una docente graba su primer video con el celular. Tiene dos opciones para mejorarlo con poco presupuesto: una cámara mejor o un micrófono sencillo y un lugar silencioso. ¿Qué le conviene más?', '["El audio claro y un lugar silencioso, porque el sonido influye más que la resolución en la comprensión.","Una cámara mejor, porque los estudiantes valoran una imagen nítida.","Una luz de anillo para que la imagen se vea profesional.","Un programa de edición para mejorar el video después."]'::jsonb, 0, 'Audio e iluminación son los dos factores clave de un video educativo.', 'exam'),
('abv', 12, 'Un docente quiere publicar en YouTube un video donde aparecen sus estudiantes explicando un experimento. ¿Qué debe hacer antes?', '["Obtener el consentimiento por escrito de las familias y considerar publicarlo como no listado.","Publicarlo, porque es una actividad escolar y no hay datos personales.","Pedir permiso a los estudiantes que aparecen, sin consultar a las familias.","Publicarlo de inmediato, porque la escuela ya tiene un permiso general."]'::jsonb, 0, 'Se requiere consentimiento informado de las familias y control de la visibilidad.', 'exam'),
('abv', 13, 'Al evaluar videos creados por estudiantes, una docente califica casi todo por lo bien editado que está. ¿Qué ajuste de rúbrica es más coherente?', '["Dar mayor peso a la precisión y claridad del contenido, y menor al efecto de edición.","Calificar sobre todo la duración y el cumplimiento del formato.","Dar el mismo peso a contenido, edición y creatividad.","Evaluar la participación oral de cada integrante del grupo, sin revisar el contenido del video."]'::jsonb, 0, 'El aprendizaje se evidencia en la precisión conceptual, no en la producción.', 'exam'),
('abv', 14, 'Para una actividad de grabación, tres estudiantes no tienen celular. ¿Qué respuesta del docente es más equitativa?', '["Pedirles que observen a otros equipos y escriban un informe.","Pedirles que consigan uno prestado fuera de clase.","Formar equipos que compartan un dispositivo y ofrecer un formato alternativo, como un cartel o una exposición oral.","Evaluarlos con una tarea distinta de menor nota."]'::jsonb, 2, 'La equidad exige alternativas que permitan demostrar el mismo aprendizaje.', 'exam'),
('abv', 15, '¿Para qué son especialmente útiles las animaciones en un video educativo?', '["Para mostrar lo invisible, como el movimiento de los átomos o el ciclo del agua","Para mantener la atención con colores y movimiento","Para reemplazar la explicación del docente en todas las materias y en todos los niveles","Para sustituir al docente cuando no quiere aparecer en cámara"]'::jsonb, 0, 'Las animaciones hacen visibles procesos abstractos o invisibles.', 'exam'),
('abv', 16, '¿Qué es un screencast?', '["Un video documental filmado en exteriores con cámara profesional","La grabación de la pantalla mientras explicas con tu voz","Un video de 15 segundos para redes sociales","Una transmisión en vivo de la clase"]'::jsonb, 1, 'Es ideal para enseñar a usar aplicaciones o plataformas paso a paso.', 'exam'),
('abv', 17, '¿Qué duración de video recomienda el curso para primaria (6-11 años)?', '["2 a 4 minutos","15 a 20 minutos","10 a 12 minutos","La misma que para secundaria"]'::jsonb, 0, 'La duración adecuada varía con la edad; en primaria se recomiendan videos cortos.', 'exam'),
('abv', 18, 'Antes de proyectar un video sobre la fotosíntesis, la docente pregunta: ''¿Qué creen que vamos a ver?''. ¿Qué técnica usa?', '["Activar predicciones","Evaluación sumativa","Repetición espaciada breve","Lectura literal"]'::jsonb, 0, 'Predecir activa conocimientos previos y da un propósito para mirar con atención.', 'exam'),
('abv', 19, '¿Qué tipo de pregunta conviene después del video?', '["''¿Qué dijo exactamente el video? Repitan en orden las tres ideas principales que presentó.''","''¿Están de acuerdo con lo que presentó? ¿Cómo se aplica en nuestra comunidad?''","''¿Quién puede resumir el video en una sola oración?''","''¿Qué dato del video recuerdan mejor?''"]'::jsonb, 1, 'Las mejores preguntas posteriores invitan a pensar y aplicar, no solo a recordar.', 'exam'),
('abv', 20, '¿Qué es una guía de visualización?', '["Una hoja breve que se completa durante el video, con preguntas y espacio para anotar","Una lista de videos recomendados para cada unidad","Un resumen del video que se entrega al terminar de verlo","Un cuestionario que se responde después de ver el video"]'::jsonb, 0, 'Estructura la atención del estudiante y deja evidencia de lo que comprendió.', 'exam'),
('abv', 21, '¿Qué ventaja única tiene el video frente a una clase expositiva?', '["Que es más corto que una clase","Que se puede repetir: el estudiante puede volver a verlo en casa cuantas veces necesite","Que presenta la información de forma más completa que el docente","Que reemplaza la práctica, porque verlo varias veces ya basta"]'::jsonb, 1, 'Poder pausar y repetir ayuda a quien necesita más tiempo para comprender.', 'exam'),
('abv', 22, '¿Dónde conviene colocar el celular al grabarte explicando?', '["Desde abajo, para que se vea todo el cuerpo","A la altura de los ojos, usando la regla de tercios","Muy cerca del rostro, para que no se vea nada del fondo","De lado, para que no parezca que lees"]'::jsonb, 1, 'A la altura de los ojos y con buen encuadre, el video se ve más natural y claro.', 'exam'),
('abv', 23, '¿Cuál es la forma más organizada de usar YouTube como recurso docente?', '["Una cuenta exclusiva para recursos docentes, con listas de reproducción por unidad","Buscar un video nuevo cada día en el momento de la clase","Usar tu cuenta personal y guardar los videos en ''Ver más tarde''","Descargar los videos y guardarlos en una carpeta del celular"]'::jsonb, 0, 'Organizar listas por tema convierte YouTube en una biblioteca reutilizable.', 'exam')
INSERT INTO public.exam_questions (course_id, idx, text, options, correct, explanation, source) VALUES
('micro-learning', 0, 'Según la curva del olvido de Ebbinghaus, ¿qué porcentaje aproximado de lo aprendido olvidamos en las primeras 24 horas sin repasar?', '["Aproximadamente el 20%","Aproximadamente el 40%","Aproximadamente el 70%","Aproximadamente el 90%"]'::jsonb, 2, 'Según la curva del olvido de Ebbinghaus, sin repaso se pierde aproximadamente el 70% de la información nueva en las primeras 24 horas (una cifra aproximada, que varía según el material). Este dato fundamenta la necesidad de estrategias como el micro-learning, que distribuyen y repiten el aprendizaje en el tiempo.', 'lesson'),
('micro-learning', 1, '¿Cuántos elementos puede manejar la memoria de trabajo humana de forma simultánea, según George Miller?', '["Entre 3 y 5 elementos","Entre 7 y 9 elementos (7 ± 2)","Entre 12 y 15 elementos","Depende completamente de la persona y no hay un límite general"]'::jsonb, 1, 'George Miller estableció en su influyente artículo de 1956 que la memoria de trabajo puede manejar 7 (±2) elementos a la vez, es decir entre 5 y 9 piezas de información. Superar este límite satura la capacidad de procesamiento y reduce el aprendizaje.', 'lesson'),
('micro-learning', 2, '¿Qué elemento de la micro-cápsula la diferencia del simple contenido breve y asegura que el aprendizaje sea activo?', '["El gancho inicial que activa la curiosidad","La calidad visual del material utilizado","El cierre con una acción concreta que el estudiante puede realizar","La duración exacta de la cápsula: ni más ni menos de 5 minutos por cápsula"]'::jsonb, 2, 'El cierre-acción es el elemento que transforma una cápsula de información en una cápsula de aprendizaje. Pedir al estudiante que haga algo con lo aprendido (responder, probar, reflexionar) consolida el conocimiento y lo hace aplicable.', 'lesson'),
('micro-learning', 3, '¿Cuál de los siguientes es un objetivo ADECUADO para una micro-cápsula de aprendizaje?', '["Comprender la historia completa de la independencia de nuestro país","Identificar dos causas principales que motivaron la independencia","Valorar la importancia de los movimientos sociales para la democracia","Estudiar el contexto político, económico y social del continente a principios del siglo XIX"]'::jsonb, 1, 'Identificar dos causas específicas es un objetivo acotado, verificable y alcanzable en el tiempo de una micro-cápsula. Los otros objetivos son demasiado amplios o abstractos para una sola cápsula de 2-10 minutos.', 'lesson'),
('micro-learning', 4, 'Un docente quiere enseñar la diferencia entre ''b'' y ''v'' en español a estudiantes de segundo primaria. ¿Qué formato de micro-cápsula sería más efectivo?', '["Una infografía con la diferencia visual entre las dos letras y sus reglas","Un texto escrito con las reglas ortográficas de uso","Un audio con ejemplos de palabras con ''b'' y ''v'' para escuchar y repetir","Un video de dibujos animados sobre el abecedario"]'::jsonb, 2, 'Aprender a distinguir sonidos requiere escucharlos, no solo verlos. Un audio con ejemplos claros de palabras con ''b'' y ''v'' activa el canal auditivo de aprendizaje, que es el más adecuado para este objetivo. El video podría funcionar si combina audio con visuales del movimiento de la boca.', 'lesson'),
('micro-learning', 5, '¿Cuál de las siguientes es una práctica recomendada al usar WhatsApp para micro-learning con estudiantes?', '["Agregar a todos los contactos del colegio al mismo grupo para mayor alcance","Enviar mensajes a cualquier hora del día para aprovechar todos los momentos libres","Establecer normas claras del grupo e informar a los padres sobre su propósito","Reenviar contenido de otros grupos para diversificar los recursos"]'::jsonb, 2, 'Las normas claras y la comunicación con las familias son fundamentales para el uso responsable de WhatsApp en educación. Sin estas bases, el grupo puede perder su propósito educativo o generar problemas de privacidad y convivencia digital.', 'lesson'),
('micro-learning', 6, '¿Cuál es la principal ventaja de organizar las micro-cápsulas en una secuencia pedagógica en lugar de usarlas de forma aislada?', '["Las secuencias son más rápidas de crear y de compartir que las cápsulas individuales","Permiten construir conceptos complejos distribuyendo el aprendizaje en el tiempo","Permiten cubrir más temas en menos tiempo de clase","Reducen la necesidad de evaluar cada cápsula por separado"]'::jsonb, 1, 'La secuencia pedagógica permite construir conceptos complejos de forma gradual, distribuyendo el aprendizaje en el tiempo y aprovechando la curva del olvido para reforzar en los momentos óptimos. Esto es imposible con cápsulas aisladas sin conexión entre sí.', 'lesson'),
('micro-learning', 7, '¿Qué es un ''ticket de salida'' en el contexto del micro-learning?', '["Un certificado que el estudiante recibe al completar todas las cápsulas de una misma secuencia","Una tarjeta o nota breve donde el estudiante escribe qué aprendió y qué pregunta le quedó","Un código QR que permite al docente registrar la asistencia digital de los estudiantes","Una evaluación sumativa de 20 preguntas al finalizar la unidad"]'::jsonb, 1, 'El ticket de salida es una estrategia de evaluación formativa rápida: el estudiante escribe en 2 minutos qué aprendió y qué duda le quedó. Informa al docente sobre la comprensión real del grupo y activa la metacognición del estudiante.', 'lesson'),
('micro-learning', 8, 'Una docente tiene una cápsula de 12 minutos con cinco ideas distintas sobre la célula. Los estudiantes terminan confundidos. ¿Qué haría el micro-learning?', '["Dividirla en cápsulas de 3 a 5 minutos, cada una con un solo objetivo y un ejemplo concreto.","Añadir más ejemplos a la misma cápsula.","Agregar subtítulos para que se entienda mejor.","Pedir que la vean dos veces seguidas en casa."]'::jsonb, 0, 'Una cápsula, un objetivo, una acción: la memoria de trabajo es limitada.', 'exam'),
('micro-learning', 9, 'Un docente enseña un tema difícil el lunes y no vuelve a mencionarlo hasta el examen del mes. ¿Qué estrategia del curso corrige esto?', '["Dar una tarea larga el domingo anterior al examen para que repasen todo el tema de una sola vez.","Repetición espaciada: repasar el tema en intervalos crecientes con mini cápsulas de repaso.","Repetir la clase completa en la semana siguiente.","Dar una guía de estudio completa una semana antes del examen."]'::jsonb, 1, 'La curva del olvido muestra que sin repaso se pierde la mayoría; el repaso espaciado la contrarresta.', 'exam'),
('micro-learning', 10, 'Una docente escribe un objetivo para su cápsula: ''Entender la fotosíntesis''. ¿Cómo lo mejoraría según el curso?', '["''Explicar con tus palabras qué necesita una planta para producir su alimento'', con verbo observable y alcanzable en la cápsula.","''Conocer las partes de la planta y la función de cada una''.","''Comprender la importancia de la fotosíntesis para la vida en el planeta''.","''Investigar todo lo que se sabe sobre la fotosíntesis y presentarlo al grupo en una exposición''."]'::jsonb, 0, 'Un buen objetivo usa un verbo observable y cabe en el tiempo de la cápsula.', 'exam'),
('micro-learning', 11, 'Un docente comparte cápsulas por WhatsApp a las 11 de la noche y los padres se quejan. ¿Qué práctica habría evitado el conflicto?', '["Acordar con las familias normas de horario, propósito y uso del grupo desde el inicio.","Enviar los mensajes en fin de semana, cuando las familias tienen tiempo.","Usar otra aplicación distinta de WhatsApp para los mensajes escolares.","Enviar todas las cápsulas de la semana juntas el lunes."]'::jsonb, 0, 'El canal funciona si hay normas claras e información previa a las familias.', 'exam'),
('micro-learning', 12, 'Una maestra quiere enseñar un concepto complejo de historia en una semana con cápsulas. ¿Qué secuencia es la más coherente?', '["Empezar por la aplicación práctica y luego explicar la teoría.","Presentar todo el contenido el lunes y repasarlo completo el viernes.","Alternar temas distintos cada día para no aburrir.","Ir de lo simple a lo complejo: qué es, cómo funciona, ejemplo local, aplicación y repaso."]'::jsonb, 3, 'Las cápsulas encadenadas construyen el concepto por capas.', 'exam'),
('micro-learning', 13, 'Al final de una cápsula, una docente pide a cada estudiante escribir qué aprendió y qué duda le quedó. ¿Cómo se llama esta estrategia y para qué sirve?', '["Autoevaluación: el estudiante se pone una nota según su esfuerzo.","Portafolio: reúne trabajos del año.","Rúbrica: define criterios de calificación.","Ticket de salida: da evidencia rápida de comprensión y orienta la siguiente cápsula."]'::jsonb, 3, 'El ticket de salida es una evaluación breve y ágil, acorde con el formato micro.', 'exam'),
('micro-learning', 14, 'Dos docentes crean una infografía. Una la llena de texto y datos; la otra incluye un concepto, tres datos y un ejemplo local. ¿Cuál se acerca más al micro-learning?', '["La segunda, porque limita el contenido a lo esencial y lo ancla en un ejemplo cercano.","La primera, porque aporta más información.","Ambas, porque las dos son visuales.","La primera, porque cada estudiante puede elegir qué datos leer."]'::jsonb, 0, 'Brevedad y ejemplo concreto son el corazón de cada cápsula.', 'exam'),
('micro-learning', 15, '¿Cuál es la regla de oro del micro-learning?', '["Una cápsula, un objetivo, una acción","Muchos temas distintos en poco tiempo","Videos cortos para cada tema","Cápsulas de dos minutos como máximo"]'::jsonb, 0, 'Cada cápsula responde a una sola pregunta o enseña una sola cosa, con una acción del estudiante.', 'exam'),
('micro-learning', 16, '¿Cuáles son las partes de una micro-cápsula efectiva?', '["Introducción, marco teórico, desarrollo y bibliografía","Gancho, núcleo del contenido y acción o cierre","Objetivo, explicación y evaluación final","Video, lectura y cuestionario"]'::jsonb, 1, 'El gancho despierta la curiosidad, el núcleo enseña el concepto y la acción hace que el estudiante lo use.', 'exam'),
('micro-learning', 17, '¿Qué técnica de escritura propone el curso para el micro-contenido?', '["Escribir de una vez y publicar rápido","Escribir, recortar lo que no es esencial y volver a simplificar","Resumir el libro de texto en viñetas","Usar términos técnicos para que sea más riguroso"]'::jsonb, 1, 'Escribir breve es más difícil: requiere eliminar todo lo que no es esencial.', 'exam'),
('micro-learning', 18, '¿Por qué cada cápsula necesita un ejemplo concreto y local?', '["Porque los conceptos abstractos se comprenden mejor anclados en algo conocido","Porque así la cápsula es más entretenida","Porque los ejemplos permiten omitir la explicación","Porque los programas oficiales lo exigen"]'::jsonb, 0, 'Un ejemplo cercano (la comida, el mercado, la comunidad) conecta el concepto con la experiencia del estudiante.', 'exam'),
('micro-learning', 19, '¿Qué es la repetición espaciada?', '["Repetir la misma clase completa todos los días","Repasar la información en intervalos crecientes: hoy, mañana, en 3 días, en una semana","Estudiar todo la noche antes del examen","Leer el mismo texto varias veces seguidas hasta memorizarlo"]'::jsonb, 1, 'Espaciar los repasos combate la curva del olvido mucho mejor que concentrarlos.', 'exam'),
('micro-learning', 20, '¿Qué propone la ''planificación en capas'' para un concepto complejo?', '["Enseñarlo en una sola sesión larga para no perder la conexión entre ideas","Dividirlo en capas por días: qué es, cómo funciona, cómo se aplica…","Empezar por lo más difícil para despertar curiosidad","Dejarlo como tarea para la casa con una guía"]'::jsonb, 1, 'Cada cápsula agrega una capa al concepto, de lo simple a lo complejo.', 'exam'),
('micro-learning', 21, '¿Qué tienen de útil las tarjetas didácticas (flashcards) digitales?', '["Permiten practicar recuperando información, y muchas plataformas programan los repasos","Reemplazan la explicación del docente","Sirven sobre todo para memorizar vocabulario de idiomas","Funcionan mejor si se repasan todas juntas antes del examen"]'::jsonb, 0, 'Recuperar la respuesta (en vez de releer) y espaciar los repasos fortalece la memoria.', 'exam'),
('micro-learning', 22, '¿Cómo se recomienda organizar el banco de micro-cápsulas?', '["Guardarlas sin orden en el celular, y buscarlas cuando se necesiten","En carpetas por unidad o tema para reutilizarlas","En un solo archivo con todas las cápsulas del año","En el chat del grupo, para que los estudiantes las busquen"]'::jsonb, 1, 'Un banco organizado permite reutilizar y encadenar cápsulas en futuras secuencias.', 'exam'),
('micro-learning', 23, '¿Cuál es un indicador cualitativo de que una secuencia de micro-learning funciona?', '["Los estudiantes hacen preguntas más profundas sobre el tema","Los estudiantes abren todas las cápsulas que se envían al grupo","Las cápsulas reciben muchas reacciones en el grupo","Los estudiantes piden más cápsulas cada semana"]'::jsonb, 0, 'Preguntas más profundas y mejor uso del concepto muestran comprensión, más allá de la cantidad de contenido consumido.', 'exam')
INSERT INTO public.exam_questions (course_id, idx, text, options, correct, explanation, source) VALUES
('ia-fundamentos', 0, '¿Qué describe MEJOR cómo funciona un modelo de IA generativa como el chat de esta plataforma?', '["Consulta una base de datos de hechos verificados y responde con la verdad exacta","Predice el contenido más probable según patrones aprendidos de muchos datos","Piensa y razona exactamente igual que un ser humano","Busca en internet en el momento y copia la respuesta más popular"]'::jsonb, 1, 'La IA generativa no "sabe" hechos como una enciclopedia: predice, palabra por palabra, el contenido más probable dado el contexto. Por eso puede sonar segura y a la vez estar equivocada — no consulta la verdad, calcula probabilidad.', 'lesson'),
('ia-fundamentos', 1, 'Un docente en una comunidad rural con acceso limitado a internet quiere empezar a usar IA. ¿Cuál es el enfoque más realista para esta ruta?', '["No tiene sentido aprender IA si sus estudiantes no tienen acceso a internet en casa","Usar la IA como herramienta de preparación docente (planificar, adaptar contenido), sin asumir que cada estudiante tendrá el mismo acceso","Usar la IA directamente con los estudiantes en clase desde el primer día","Esperar a que la escuela tenga internet estable antes de aprender a usarla"]'::jsonb, 1, 'Esta ruta prioriza el uso docente de la IA como herramienta de preparación y planificación — algo que el docente puede aprovechar hoy sin depender del acceso de cada estudiante, mientras la brecha digital se cierra gradualmente en el país.', 'lesson'),
('ia-fundamentos', 2, '¿Cuál de los siguientes prompts está mejor construido para obtener una respuesta útil y aplicable?', '["\"Dame ideas de ciencias\"","\"Ayúdame con una clase de ciencias para mis estudiantes, que sea muy interesante, creativa, divertida y que les guste mucho a todos ellos\"","\"Soy docente de 3.º de primaria. Dame 3 actividades de 10 minutos sobre el ciclo del agua usando materiales caseros, en formato de lista\"","\"Explícame la inteligencia artificial\""]'::jsonb, 2, 'El tercer prompt incluye contexto (grado, país), tarea específica (3 actividades sobre el ciclo del agua), restricciones (10 minutos, materiales caseros) y formato (lista). Esa especificidad reduce la necesidad de reescribir la respuesta después.', 'lesson'),
('ia-fundamentos', 3, 'La primera respuesta que te da la IA resulta demasiado avanzada para tus estudiantes de primer grado. ¿Qué deberías hacer?', '["Pedirle la misma actividad a otra herramienta de IA","Aceptar la respuesta tal cual, ya que la IA \"sabe más\" que el docente","Responder en la misma conversación pidiendo que adapte el contenido a un nivel más sencillo, ya que la IA recuerda el contexto","Empezar una conversación completamente nueva desde cero cada vez que algo no sale bien"]'::jsonb, 2, 'La IA funciona como una conversación continua: puedes pedir ajustes directamente ("hazlo más sencillo", "adáptalo a primer grado") sin perder el contexto ya construido. Iterar es más eficiente que empezar de cero o descartar la herramienta.', 'lesson'),
('ia-fundamentos', 4, 'Un docente en una escuela multigrado necesita explicar el mismo tema a estudiantes de 2do y 6to primaria en la misma sesión. ¿Cómo puede ayudar la IA aquí?', '["Generando una sola explicación intermedia que sirva para ambos grados","Generando dos versiones del mismo contenido, una para cada nivel","Pidiendo la explicación para 6.º y simplificándola en clase para 2.º","Pidiendo actividades sobre temas distintos para cada grado"]'::jsonb, 1, 'La IA puede generar múltiples versiones adaptadas de un mismo contenido si se lo pides explícitamente para cada nivel — una ventaja real en el contexto de escuelas multigrado, muy común en el área rural de muchos países.', 'lesson'),
('ia-fundamentos', 5, '¿Qué significa que una IA "alucine" un dato?', '["Que el sistema tiene una falla técnica y deja de funcionar","Que inventa información falsa y la presenta con total seguridad","Que repite la misma respuesta aunque cambies la pregunta","Que la IA se niega a responder la pregunta porque detecta que el tema es demasiado complejo"]'::jsonb, 1, 'Una "alucinación" ocurre cuando la IA genera información incorrecta o inventada —una fecha, un dato, una cita— pero la presenta con la misma confianza que un dato verificado. Por eso siempre hay que confirmar la información importante en una fuente confiable.', 'lesson'),
('ia-fundamentos', 6, '¿Cuál de las siguientes acciones representa un riesgo de privacidad al usar IA?', '["Pedir a la IA una actividad genérica sobre fracciones","Escribir en el chat: \"Juan Pérez, del 4to B, tiene esta calificación en matemáticas: 45. Ayúdame a redactar una nota para sus padres explicando sus dificultades\"","Pedir a la IA que explique un concepto de ciencias de forma sencilla","Solicitar una rúbrica genérica de evaluación para un proyecto de ciencias de 5.º grado, con cuatro criterios y cuatro niveles de desempeño, sin datos de ningún estudiante"]'::jsonb, 1, 'Compartir el nombre completo de un estudiante junto con datos sensibles como calificaciones específicas expone información privada de un menor de edad en una herramienta externa. La forma correcta es describir la situación de manera general, sin identificar a la persona.', 'lesson'),
('ia-fundamentos', 7, 'Un docente planea usar IA como parte de una actividad directa con sus estudiantes en un centro rural con acceso desigual a internet. ¿Cuál es la decisión más equitativa?', '["Asumir que todos los estudiantes pueden usar IA en casa para la tarea","Hacer la actividad en el aula, con supervisión, y no como tarea en casa","Posponer el uso de IA con estudiantes hasta que todos tengan internet estable en casa","Dejar que participen los estudiantes con teléfono propio y que los demás observen"]'::jsonb, 1, 'Cuando el acceso a internet o dispositivos no es garantizado para todos, la opción más equitativa es que el uso de IA con estudiantes ocurra en el aula bajo supervisión docente, evitando que la brecha digital se traduzca en una brecha de aprendizaje.', 'lesson'),
('ia-fundamentos', 8, 'En esta ruta, ¿cuál es la idea central que debe guiar el uso de la IA en la práctica docente?', '["La IA es confiable para casi todo, así que basta con revisar de vez en cuando","La IA es una herramienta de apoyo que acelera tareas mecánicas, pero el criterio pedagógico, la verificación de datos y las decisiones sobre estudiantes siguen siendo responsabilidad humana del docente","La IA debe usarse sobre todo con los estudiantes, no en la planificación","La IA puede encargarse de planificar, de modo que el docente dedique ese tiempo a calificar y a los registros administrativos"]'::jsonb, 1, 'El hilo conductor de todo este curso es el equilibrio: aprovechar la velocidad y versatilidad de la IA para tareas de preparación y borrador, mientras el juicio pedagógico, la verificación y las decisiones sobre estudiantes reales permanecen firmemente en manos del docente.', 'lesson'),
('ia-fundamentos', 9, 'Una docente pide a la IA un dato histórico y recibe una fecha y una cita textual muy convincentes. Al buscar, la cita no existe. ¿Qué ocurrió y qué debió hacer?', '["La IA mintió a propósito; debió desconfiar de toda herramienta digital.","La IA ''alucinó'': inventó un dato con seguridad; debió verificar en una fuente confiable antes de usarlo.","La cita es real pero está en otro idioma; debió traducirla.","La IA usó una fuente desactualizada; debió pedir una más reciente."]'::jsonb, 1, 'Las alucinaciones son respuestas falsas con tono seguro; el docente siempre valida.', 'exam'),
('ia-fundamentos', 10, 'Un docente escribe: ''Dame ideas para enseñar fracciones''. La respuesta es genérica. ¿Cuál es la mejora más útil?', '["Añadir contexto y restricciones: grado, duración, materiales y número de ideas.","Pedir ''más ideas'' en el mismo chat.","Agregar ''por favor'' y ''gracias'' para que la IA responda mejor.","Cambiar de herramienta sin modificar el prompt."]'::jsonb, 0, 'Un buen prompt combina contexto, tarea, formato y restricciones.', 'exam'),
('ia-fundamentos', 11, 'Una directora pide a un docente que use la IA para elaborar el informe oficial del ministerio. ¿Qué es lo más adecuado?', '["Pegar la salida de la IA sin leerla para ahorrar tiempo.","Rechazar toda ayuda de IA aunque ahorre horas de trabajo.","Incluir en el prompt los nombres completos y las notas de los estudiantes, para que el informe quede más personalizado.","Usarla como apoyo de redacción, revisarlo todo y declarar su uso si se pide."]'::jsonb, 3, 'Uso responsable y transparente: validar, proteger datos y declarar cuando corresponda.', 'exam'),
('ia-fundamentos', 12, 'Un docente teme que la IA lo reemplace. Su colega responde con un argumento que recoge la idea del curso. ¿Cuál es?', '["La IA no conoce a sus estudiantes ni sostiene un vínculo; automatiza tareas mecánicas, no el criterio ni la relación pedagógica.","La IA mejorará tanto en pocos años que solo habrá que supervisar su trabajo en el aula.","La IA comete errores, así que nunca podrá usarse en educación.","Las leyes impiden que la IA trabaje en las escuelas."]'::jsonb, 0, 'El vínculo pedagógico y el juicio profesional no se delegan.', 'exam'),
('ia-fundamentos', 13, 'En una escuela con conexión limitada, una docente quiere empezar con IA. ¿Qué estrategia es más realista?', '["Usarla en su preparación: generar borradores y adaptaciones sin exigir que cada estudiante tenga acceso.","Pedir que cada estudiante use la IA en casa para las tareas.","Esperar a tener internet de alta velocidad en todo el centro.","Usar la IA solo con los estudiantes que tienen internet, como incentivo."]'::jsonb, 0, 'Empezar por la preparación docente no excluye a quien no tiene acceso.', 'exam'),
('ia-fundamentos', 14, 'Al usar IA con estudiantes, una docente nota que las imágenes que genera muestran siempre los mismos estereotipos. ¿Qué lección del curso aplica?', '["La IA es neutral; los estudiantes interpretan mal.","Los modelos reflejan sesgos de sus datos de entrenamiento; conviene revisar, corregir el prompt y conversarlo con el grupo.","Es un error de la herramienta que se corrige pidiendo otra imagen.","Es mejor dejar de mostrar resultados de IA en clase."]'::jsonb, 1, 'Los sesgos son un límite conocido y un excelente punto de pensamiento crítico.', 'exam'),
('ia-fundamentos', 15, '¿Qué diferencia a la IA moderna de un programa tradicional?', '["La IA moderna sigue reglas fijas que un programador escribe una por una para cada caso posible del sistema","La IA moderna aprende patrones a partir de muchos ejemplos, sin una regla escrita para cada caso","La IA moderna busca la respuesta en internet en el momento","La IA moderna razona igual que una persona, pero más rápido"]'::jsonb, 1, 'Los programas tradicionales siguen reglas explícitas; la IA moderna aprende patrones de millones de ejemplos. Por eso puede responder a casos nuevos, pero también equivocarse con seguridad.', 'exam'),
('ia-fundamentos', 16, '¿Qué tipo de IA genera textos, imágenes o audio nuevos a partir de una instrucción?', '["La IA clásica de clasificación, como un filtro de spam","Un asistente de voz que ejecuta comandos predefinidos","La IA generativa","Un buscador que muestra páginas web ya existentes"]'::jsonb, 2, 'La IA generativa crea contenido nuevo a partir de un prompt. La IA clásica clasifica o predice, y un buscador solo encuentra lo que ya existe.', 'exam'),
('ia-fundamentos', 17, 'Un modelo de lenguaje responde con mucha seguridad una pregunta de historia. ¿Qué conviene recordar?', '["Genera la respuesta más probable según patrones, no consulta una base de verdades, así que puede equivocarse","Si responde con tanta seguridad es porque antes verificó la información en fuentes oficiales y confiables de historia","Los modelos de lenguaje responden cuando tienen el dato exacto guardado","La seguridad del tono indica que el dato fue revisado por expertos"]'::jsonb, 0, 'Un modelo de lenguaje construye una respuesta plausible palabra por palabra. El tono seguro no garantiza que sea cierta: hay que verificar.', 'exam'),
('ia-fundamentos', 18, 'Según el curso, ¿cuáles son los 4 elementos de un buen prompt?', '["Rol, pregunta, ejemplos y tono","Contexto, tarea, formato y restricciones","Título, introducción, desarrollo y conclusión","Tema, número de palabras, idioma y fecha de entrega"]'::jsonb, 1, 'Un prompt efectivo dice quién eres y para quién es (contexto), qué necesitas (tarea), cómo lo quieres (formato) y qué límites tiene (restricciones).', 'exam'),
('ia-fundamentos', 19, 'Un docente escribe al inicio: ''Actúa como un docente con 20 años de experiencia en escuelas rurales''. ¿Qué técnica está usando?', '["Restringir el formato de la respuesta","Pedirle a la IA que verifique sus fuentes","Darle un rol a la IA para orientar el tono y el enfoque","Compartir datos personales para personalizar la respuesta"]'::jsonb, 2, 'Asignar un rol orienta el tono y el enfoque de lo que la IA genera. Es una de las técnicas más simples para mejorar la calidad de la respuesta.', 'exam'),
('ia-fundamentos', 20, 'Una docente necesita un texto para leer en voz alta a primer grado. ¿Qué parte del prompt es más importante agregar?', '["Un formato explícito: ''máximo 100 palabras, en lenguaje sencillo''","Una petición de que la IA use vocabulario técnico para enriquecerlo","El nombre completo de cada estudiante del grupo","Nada más: la IA adivina el nivel adecuado por el tema"]'::jsonb, 0, 'Cuanto más claro es el formato pedido (longitud, nivel de lenguaje), más útil es el resultado. La IA no adivina el nivel de tu grupo.', 'exam'),
('ia-fundamentos', 21, 'La IA te da ejemplos de fracciones con monedas y productos que tus estudiantes no conocen. ¿Qué haces?', '["Usarlos igual, porque las fracciones son las mismas en todo lugar","Pedir ejemplos anclados en tu contexto, como el reparto de comida en una mesa familiar","Dejar de usar IA para matemáticas","Pedir que la IA explique las fracciones sin ningún ejemplo concreto"]'::jsonb, 1, 'Los modelos aprenden sobre todo de contenidos de otros países y pueden traer ejemplos ajenos. Pedir explícitamente ejemplos locales corrige ese sesgo.', 'exam'),
('ia-fundamentos', 22, '¿Por qué la IA puede reflejar sesgos culturales en sus respuestas?', '["Porque fue programada para favorecer a ciertos países","Porque aprende de textos e imágenes producidos mayoritariamente en otros países e idiomas","Porque los docentes la usan con prompts demasiado cortos","Porque traduce del inglés todo lo que responde en español"]'::jsonb, 1, 'Los datos de entrenamiento provienen mayoritariamente de otros contextos, así que los ejemplos y supuestos pueden no reflejar a tu comunidad. Revísalos con mirada crítica.', 'exam'),
('ia-fundamentos', 23, '¿Qué decisión NO debería delegarse nunca en una herramienta de IA?', '["Redactar el borrador de una circular para las familias","Generar un banco de 10 preguntas de repaso sobre un tema que ya se enseñó en clase durante la semana","Decidir si un estudiante está listo para avanzar de nivel o necesita apoyo socioemocional","Proponer tres analogías para explicar la electricidad"]'::jsonb, 2, 'Las decisiones sobre estudiantes concretos requieren conocerlos y juicio profesional. La IA puede hacer borradores, no decidir por ti.', 'exam')
INSERT INTO public.exam_questions (course_id, idx, text, options, correct, explanation, source) VALUES
('ia-tiempo', 0, '¿Cuál es la mentalidad correcta que propone este curso para usar la IA y ahorrar tiempo sin perder calidad?', '["Dejar que la IA decida las calificaciones finales de los estudiantes","Usar la IA para generar borradores rápidos que el docente revisa y ajusta antes de usarlos","Evitar la IA por completo para no perder el control pedagógico","Usar lo que la IA genera tal cual, porque ya viene bien redactado y revisado por el sistema"]'::jsonb, 1, 'El patrón central de este curso es "borrador rápido + revisión humana": la IA acelera la parte mecánica de redactar un primer borrador, mientras el docente conserva el control sobre calificaciones, decisiones pedagógicas y ajustes finales.', 'lesson'),
('ia-tiempo', 1, 'Un docente que enseña la misma materia en 3ro y 5to primaria ya tiene una planificación completa para 5to. ¿Cómo puede ahorrar tiempo con IA para la clase de 3ro?', '["Pedirle a la IA una planificación nueva para 3ro sin compartirle la de 5to","Puede pedirle a la IA que adapte la planificación existente de 5to, simplificando vocabulario y actividades para 3ro","Usar la de 5to tal cual y explicar más despacio en clase","Pedirle a la IA que resuma la de 5to a la mitad de su extensión"]'::jsonb, 1, 'Pedir a la IA que adapte un material ya existente a otro nivel es mucho más rápido que partir de cero, y aprovecha el trabajo de calidad que el docente ya invirtió en la planificación original.', 'lesson'),
('ia-tiempo', 2, '¿Cuál es la forma correcta de usar la IA en el proceso de calificación, según este curso?', '["Subir el trabajo completo del estudiante y pedirle a la IA que asigne la calificación final","Usar la IA para generar bancos de frases de retroalimentación y ejercicios de refuerzo, mientras el docente conserva la decisión final sobre la calificación","No usar la IA en ninguna parte del proceso, ni siquiera para redactar comentarios","Dejar que la IA califique los exámenes de opción múltiple y revisar solo los abiertos"]'::jsonb, 1, 'La IA puede acelerar tareas como redactar retroalimentación variada o generar ejercicios de refuerzo, pero la calificación final —que requiere conocer el contexto completo del estudiante— sigue siendo una decisión exclusivamente del docente.', 'lesson'),
('ia-tiempo', 3, 'Un docente recibe un documento largo con una nueva política institucional y necesita decidir rápido si aplica a su caso. ¿Cuál es el mejor uso de la IA en esta situación?', '["Leerlo completo de inmediato, aunque le tome toda la tarde","Pedir un resumen de puntos clave para decidir si debe leerlo completo","Actuar directamente según el resumen de la IA, sin verificar el documento original","Reenviarlo a un colega para que le cuente de qué trata"]'::jsonb, 1, 'Un resumen generado por IA es un excelente punto de partida para decidir la urgencia de un documento, pero en asuntos con implicaciones legales o administrativas importantes, siempre conviene verificar el texto original antes de tomar una decisión final.', 'lesson'),
('ia-tiempo', 4, '¿Cuál es el criterio central para decidir qué tareas SÍ automatizar con IA y cuáles mantener completamente manuales?', '["Automatizar todo lo que se pueda, revisando al azar algunos resultados para controlar la calidad","Automatizar lo mecánico y los borradores; decidir uno mismo lo que requiere criterio sobre estudiantes concretos (notas finales, conversaciones sensibles)","No automatizar nada, porque cualquier texto de IA puede contener errores","Automatizar sobre todo la comunicación con familias, que es lo que más tiempo consume"]'::jsonb, 1, 'El criterio que atraviesa todo este curso es la distinción entre tareas mecánicas de borrador (donde la IA aporta velocidad real) y decisiones que requieren juicio humano directo sobre un estudiante o situación específica (donde la IA no debe sustituir al docente).', 'lesson'),
('ia-tiempo', 5, 'Una docente cronometró que redacta cada plan semanal en 90 minutos. Con IA tarda 25, pero luego necesita 20 para revisar y ajustar. ¿Cómo debe calcular su ahorro?', '["Sumando el tiempo de revisión: de 90 a 45 minutos, es decir, ahorra unos 45 minutos.","Considerando solo los 25 minutos de generación: ahorra 65.","Restando solo el tiempo de revisión: ahorra unos 70 minutos.","Ahorra los 90 minutos completos, porque la IA hace el trabajo y la revisión es opcional."]'::jsonb, 0, 'El ahorro real incluye la revisión; así se mide con honestidad.', 'exam'),
('ia-tiempo', 6, 'Durante la primera semana usando IA, un docente se siente más lento. ¿Qué interpretación es correcta?', '["Es señal de que la IA no sirve para su área.","Debe cambiar de herramienta hasta encontrar una que sea mucho más rápida desde el primer día.","Conviene dejarla unas semanas y volver cuando la herramienta mejore.","Es normal: aprender a formular buenos prompts toma práctica y el ahorro aparece con el uso."]'::jsonb, 3, 'La curva de aprendizaje inicial es normal.', 'exam'),
('ia-tiempo', 7, 'Un docente de 3.º y 5.º tiene una planificación que funcionó en 5.º. ¿Cuál es la forma más eficiente de usar la IA?', '["Pedirle que adapte esa planificación al nivel de 3.º, indicando objetivos y duración, y luego revisar el resultado.","Pedirle una planificación nueva desde cero cada vez.","Copiar la planificación de 5.º sin cambios, porque los contenidos de ambos grados son parecidos y el tiempo no alcanza.","Pedirle que decida qué contenidos corresponden a 3.º sin dar contexto."]'::jsonb, 0, 'Adaptar un material propio ahorra tiempo y conserva lo que ya sabes que funciona.', 'exam'),
('ia-tiempo', 8, 'Una docente pide a la IA una rúbrica para evaluar un proyecto. La rúbrica incluye criterios que no trabajó en clase. ¿Qué debe hacer?', '["Usarla tal cual, porque los criterios extra elevan la exigencia.","Ajustar los criterios a lo realmente enseñado antes de usarla; la IA solo propone un borrador.","Pedir a la IA otra rúbrica distinta y quedarse con la que tenga menos criterios en total para evaluar.","Ajustar el proyecto para que coincida con la rúbrica propuesta."]'::jsonb, 1, 'La coherencia entre lo enseñado y lo evaluado es responsabilidad del docente.', 'exam'),
('ia-tiempo', 9, 'Un docente quiere usar la IA para calcular la nota final de cada estudiante a partir de sus trabajos. ¿Qué recomienda el curso?', '["Usarla para bancos de comentarios y borradores, pero decidir él mismo la calificación final.","Delegar toda la calificación a la IA para ahorrar tiempo.","No usar IA en ninguna parte de la retroalimentación.","Pedirle que califique todo y revisar solo las notas más bajas."]'::jsonb, 0, 'La línea que la IA no debe cruzar: la decisión de la nota.', 'exam'),
('ia-tiempo', 10, 'Antes de enviar una circular redactada con IA a las familias, ¿qué paso es indispensable?', '["Pedir a la IA que la revise y enviarla si no encuentra errores.","Leerla completa y ajustar tono, datos, fechas y nombres, verificando que no incluya información errónea.","Agregar el logotipo de la escuela para que se vea oficial.","Reducirla a una sola línea para evitar errores."]'::jsonb, 1, 'Saltarse la revisión elimina el rol de validación del docente.', 'exam'),
('ia-tiempo', 11, 'Una maestra recibe un documento institucional de 40 páginas y tiene 10 minutos. ¿Qué uso de IA es más apropiado?', '["Aceptar el resumen de la IA como suficiente y no leer ninguna otra parte del documento institucional original.","Leer solo el índice y dejar el resto para el fin de semana.","Pedir un resumen de puntos clave y luego leer a fondo las secciones que le afecten directamente.","Pedir a la IA que redacte una respuesta para la dirección."]'::jsonb, 2, 'El resumen orienta, pero la lectura de lo relevante sigue siendo del docente.', 'exam'),
('ia-tiempo', 12, 'Un colega dice: ''Si la IA planifica y califica por mí, mi trabajo no vale nada''. ¿Cómo responder según el curso?', '["Tiene razón; conviene dejar de usar la IA.","Debe usarla en todo para no quedarse atrás.","Tiene razón en parte; conviene usarla solo para las tareas administrativas del centro.","Su valor está en el criterio y el vínculo; la IA solo le quita tareas mecánicas."]'::jsonb, 3, 'Asistente, no reemplazo: el ahorro es costo de oportunidad a favor de lo humano.', 'exam'),
('ia-tiempo', 13, 'Una docente quiere decidir qué tareas de su semana automatizar. ¿Qué criterio es más útil?', '["Automatizar lo más difícil y dejar para sí lo fácil.","Automatizar tareas repetitivas de borrador y reservar para sí las que requieren juicio, contexto y relación con los estudiantes.","Automatizar todo lo que se pueda, sin importar el tipo de tarea.","Automatizar sobre todo la comunicación con las familias, que es lo más lento."]'::jsonb, 1, 'Mecánico y de borrador sí; criterio y vínculo no.', 'exam'),
('ia-tiempo', 14, 'Una docente de multigrado necesita tres versiones de una actividad: simplificada, estándar y de desafío. ¿Qué prompt es mejor?', '["''Crea tres versiones de esta actividad de fracciones para 4.º: con apoyos visuales, estándar y de extensión.''","''Hazme algo de fracciones.''","''Crea una actividad mejor.''","''Dame todo lo que sepas sobre diferenciación y planifica el mes completo de actividades por mí, sin más datos del grupo.''"]'::jsonb, 0, 'Pedir variantes concretas y acotadas es un uso de alto ahorro.', 'exam'),
('ia-tiempo', 15, 'Según el curso, ¿cuáles son los tres bloques que concentran el tiempo ''invisible'' del docente?', '["Reuniones, capacitaciones y trámites administrativos","Planificar, calificar y dar retroalimentación, y comunicar","Dar clase, atender a las familias y cuidar los recreos del día","Preparar materiales, decorar el aula y organizar actos"]'::jsonb, 1, 'Planificar desde cero, calificar con comentarios y redactar comunicaciones son las tareas repetitivas donde la IA puede ahorrar tiempo.', 'exam'),
('ia-tiempo', 16, 'El curso propone pensar en la IA como:', '["Un reemplazo del docente que puede planificar todas las clases por él, sin necesidad de revisión","Un asistente junior muy rápido, pero sin experiencia en tu aula, cuyo trabajo siempre revisas","Un sistema que califica de forma más justa que una persona","Un buscador más rápido para encontrar materiales ya hechos"]'::jsonb, 1, 'La mentalidad de la ruta es ''borrador rápido + revisión experta'': la IA produce un primer borrador y tú decides qué se queda.', 'exam'),
('ia-tiempo', 17, 'Una docente detecta que muchos estudiantes confunden suma con multiplicación en los problemas. ¿Cómo puede ayudar la IA?', '["Pidiéndole que califique todos los trabajos para saber quién se equivocó y en qué","Describiendo el error común y pidiendo 2 o 3 ejercicios enfocados en corregirlo","Pidiéndole que explique el tema con más palabras técnicas","Pidiéndole una lista de problemas del libro para repetirlos"]'::jsonb, 1, 'Convertir un patrón de error observado en ejercicios específicos de refuerzo es una tarea mecánica donde la IA ahorra tiempo real.', 'exam'),
('ia-tiempo', 18, 'Un docente quiere comentarios de boleta más personalizados sin pasar horas escribiéndolos. ¿Qué propone el curso?', '["Pedir a la IA un comentario genérico y copiarlo igual para todos","Subir los trabajos con nombre y notas para que la IA los evalúe","Describir en pocas palabras el desempeño del estudiante, pedir un borrador y ajustarlo con su conocimiento","Reutilizar los comentarios del periodo anterior"]'::jsonb, 2, 'Una descripción breve (sin datos sensibles) permite obtener un borrador constructivo que tú ajustas con detalles que solo tú conoces.', 'exam'),
('ia-tiempo', 19, '¿Para qué sirve pedir a la IA una checklist de autoevaluación para los estudiantes?', '["Para que la IA califique cada trabajo antes que el docente","Para que los estudiantes revisen su trabajo antes de entregarlo y reduzcan errores evitables","Para reemplazar la rúbrica del proyecto","Para que las familias controlen las tareas en casa"]'::jsonb, 1, 'Una lista de 5-6 puntos (¿incluí introducción?, ¿revisé la ortografía?) reduce errores que de otra forma tendrías que señalar tú al calificar.', 'exam'),
('ia-tiempo', 20, 'En respuestas abiertas, ¿cuál es un uso de la IA que acelera la revisión sin delegar el criterio?', '["Pedirle que compare la respuesta con los puntos clave de la rúbrica y señale qué falta, y luego decidir tú la nota","Pedirle que asigne la nota final y registrarla tal cual","Pedirle que ordene las respuestas de mejor a peor y calificar por posición","Pedirle que decida qué estudiantes deben repetir el examen"]'::jsonb, 0, 'La IA puede resaltar qué elementos están presentes o ausentes; la calificación sigue siendo decisión del docente.', 'exam'),
('ia-tiempo', 21, 'Una docente debe comunicar un cambio de horario a familias con distintos niveles de escolaridad. ¿Qué uso de la IA es adecuado?', '["Pedirle una versión más extensa para que no falte ningún detalle","Pedir una versión en lenguaje más simple y directo, sin perder la información esencial","Pedirle una versión más formal y técnica, para que el comunicado se vea más profesional","Enviar el comunicado tal como lo genere para ahorrar tiempo"]'::jsonb, 1, 'Simplificar el lenguaje (no traducir) ayuda a que todas las familias entiendan. Como siempre, revisas el texto antes de enviarlo.', 'exam'),
('ia-tiempo', 22, 'Antes de una reunión de padres, ¿cómo puede ayudarte la IA?', '["Decidiendo qué temas son importantes para tu grupo","Redactando una agenda organizada con tiempos estimados a partir de los puntos que tú le das","Respondiendo en tu lugar las preguntas de las familias","Eligiendo qué familias deben asistir"]'::jsonb, 1, 'Tú defines los puntos; la IA los organiza en una agenda clara. Eso ahorra preparación y hace la reunión más eficiente.', 'exam'),
('ia-tiempo', 23, 'Un docente pega un texto de su clase y pide a la IA una guía de estudio. ¿Qué ventaja tiene?', '["Convierte material que ya preparó en un recurso de repaso en pocos minutos","Garantiza que todos aprueben el examen","Reemplaza la necesidad de explicar el tema en clase, porque la guía ya lo explica","Evita tener que revisar el contenido generado"]'::jsonb, 0, 'Reutilizar tu propio material como base para una guía (puntos clave, definiciones, preguntas) es un ahorro de tiempo real. Igual conviene revisarla.', 'exam')
INSERT INTO public.exam_questions (course_id, idx, text, options, correct, explanation, source) VALUES
('ia-herramientas', 0, 'Un docente quiere crear una imagen para ilustrar el ciclo del agua en su cartel de clase. ¿Qué categoría de herramienta de IA necesita?', '["Una herramienta de voz (texto a audio)","Una herramienta de imagen (generación visual)","Una herramienta de texto, como un chat","Una herramienta de presentación de diapositivas"]'::jsonb, 1, 'Cuando la necesidad es generar material visual —un dibujo, una ilustración, un cartel— la categoría correcta es una herramienta de IA de imagen, distinta de las herramientas de texto o voz.', 'lesson'),
('ia-herramientas', 1, 'Un docente tiene un texto de nivel avanzado y necesita una versión más sencilla para un estudiante de primaria baja. ¿Cuál es el mejor prompt?', '["\"Escribe un texto fácil sobre el mismo tema para primaria\"","\"Simplifica este texto para un estudiante de 2do primaria, manteniendo la idea principal\" (pegando el texto original)","\"Resume este texto en una línea\" (pegando el texto original)","\"Explica este texto con palabras técnicas más precisas\""]'::jsonb, 1, 'Pegar el texto original y pedir explícitamente que se simplifique para un nivel específico, manteniendo la idea principal, es la forma correcta de usar la IA de texto para esta tarea de adaptación.', 'lesson'),
('ia-herramientas', 2, '¿Qué necesitas para generar una imagen educativa con una herramienta de IA gratuita como Canva?', '["Saber usar antes programas de diseño profesional, como Photoshop o Illustrator","Describir con claridad lo que necesitas, sin experiencia previa en diseño","Una suscripción de pago para poder generar imágenes","Tener una computadora especializada en diseño gráfico"]'::jsonb, 1, 'Las herramientas modernas de IA para imagen permiten generar material visual a partir de una simple descripción en palabras, sin necesitar habilidades previas de diseño gráfico ni software especializado.', 'lesson'),
('ia-herramientas', 3, 'Un docente tiene un plan de datos móviles limitado y necesita usar herramientas de IA con cuidado. ¿Qué estrategia es más razonable?', '["Evitar las herramientas de IA hasta tener un plan de datos más amplio","Priorizar el uso de herramientas que consumen menos datos (como chat de texto) fuera del wifi, y reservar generación de imágenes para cuando tenga acceso a wifi","Usar sobre todo herramientas de imagen, que rinden más por consulta","Descargar todas las imágenes de una vez el fin de semana con datos móviles"]'::jsonb, 1, 'Ser estratégico sobre cuándo usar herramientas que consumen más datos (como generación de imágenes) versus las más ligeras (como chat de texto) permite aprovechar la IA sin generar un gasto excesivo en un contexto de recursos de datos limitados.', 'lesson'),
('ia-herramientas', 4, '¿Cuál es la idea central de este curso sobre cómo abordar las herramientas de IA disponibles?', '["Es necesario conocer muchas herramientas distintas para tener opciones en cada caso que aparezca","Elegir 2-3 herramientas bien entendidas según tus necesidades, en vez de acumular muchas","Conviene pagar una suscripción para cada necesidad","Las herramientas de IA no son útiles sin conocimientos técnicos avanzados"]'::jsonb, 1, 'El curso propone un enfoque práctico: identificar tu necesidad real (texto, imagen, voz u organización) y dominar bien 2-3 herramientas gratuitas específicas, en vez de dispersarte intentando usar muchas herramientas superficialmente.', 'lesson'),
('ia-herramientas', 5, 'Una docente necesita un cartel ilustrado del ciclo del agua y también preguntas de comprensión sobre un cuento. ¿Qué criterio del curso debe guiar su elección de herramientas?', '["Usar una sola herramienta para todo, para no complicarse.","Probar todas las herramientas disponibles antes de empezar.","Elegir la herramienta según la tarea: una de imagen para el cartel y una de texto para las preguntas.","Elegir una sola herramienta, la que tenga más funciones, aunque tarde más tiempo en aprender a usarla."]'::jsonb, 2, 'La pregunta clave es qué tarea necesito resolver, no qué herramienta está de moda.', 'exam'),
('ia-herramientas', 6, 'Una docente se registra en una herramienta nueva con la misma contraseña de su correo personal. ¿Qué riesgo corre y qué debió hacer?', '["Ninguno, si la herramienta es conocida y tiene muchos usuarios.","Si la herramienta se vulnera, podrían acceder a su correo; debió usar una contraseña distinta y propia para cada servicio.","Solo corre riesgo si usa la herramienta desde el celular.","El riesgo es olvidarla; debió anotarla en su cuaderno."]'::jsonb, 1, 'Crear cuentas de forma segura incluye contraseñas únicas.', 'exam'),
('ia-herramientas', 7, 'Un docente prueba tres herramientas de imagen nuevas cada semana y no domina ninguna. ¿Qué rutina propone el curso?', '["Dedicar unos 10 minutos semanales a explorar una sola herramienta y quedarse con 2 o 3 que resuelvan tareas reales.","Seguir probando todas hasta encontrar la perfecta.","Abandonar las herramientas de IA por abrumadoras.","Elegir la herramienta con más descargas y aprenderla a fondo."]'::jsonb, 0, 'Explorar de a poco y consolidar evita la saturación.', 'exam'),
('ia-herramientas', 8, 'Una maestra genera con IA una imagen de ''un científico'' para su cartel y aparece siempre el mismo perfil de persona. ¿Qué paso del curso corresponde?', '["Aceptar la imagen porque la IA es neutral.","Revisar la diversidad de lo generado y pedir personas diversas en el prompt.","Cambiar a otra herramienta de imagen.","Usar una foto de internet en lugar de la imagen generada, para evitar el problema."]'::jsonb, 1, 'Al generar personas, se revisa la representación y se corrige el prompt.', 'exam'),
('ia-herramientas', 9, 'Una docente con datos móviles limitados quiere usar IA de voz e imagen en su clase. ¿Qué estrategia es mejor?', '["Generar todo en vivo durante la clase con los datos móviles, para que vean cómo funciona cada herramienta.","Evitar toda herramienta digital por el costo de los datos.","Preparar el material con anticipación usando Wi-Fi y descargarlo para usarlo sin conexión.","Pedir a los estudiantes que usen sus datos personales."]'::jsonb, 2, 'Planificar el uso de datos hace viable la IA en contextos de recursos limitados.', 'exam'),
('ia-herramientas', 10, 'Un docente quiere que un estudiante con dificultad lectora acceda a un texto. ¿Qué combinación aprovecha mejor las herramientas de voz?', '["Ofrecer el mismo contenido en texto y en audio mediante texto a voz para que el estudiante elija.","Dar el texto y pedirle que lo lea en casa con más tiempo.","Reemplazar el texto por audio para todo el grupo.","Pedir a un compañero que se lo lea en voz alta en clase."]'::jsonb, 0, 'Combinar texto y audio llega a más estudiantes.', 'exam'),
('ia-herramientas', 11, 'Una docente usa una imagen generada por IA en un cuadernillo que quiere compartir. ¿Qué debe revisar?', '["Las condiciones de uso de la herramienta respecto a derechos de autor y si indica el uso de IA.","Nada, porque cualquier imagen de IA es de uso libre.","Que la imagen tenga buena resolución para imprimir.","Que la imagen no tenga marcas de agua visibles."]'::jsonb, 0, 'Los términos de uso y la transparencia importan con el material generado.', 'exam'),
('ia-herramientas', 12, 'Una herramienta gratuita limita los usos diarios y luego pide pago. ¿Cómo debe actuar un docente prudente?', '["Aprovechar el límite gratuito para sus tareas clave y mantener alternativas, sin depender de una sola herramienta.","Pagar de inmediato para no perder acceso.","Crear varias cuentas gratuitas para ampliar el límite diario.","Dejar de preparar material hasta que se renueve el límite."]'::jsonb, 0, 'Entender ''gratis'' frente a ''freemium'' evita dependencia.', 'exam'),
('ia-herramientas', 13, 'El curso termina con la idea de que no hace falta dominar todas las herramientas. ¿Qué actitud la refleja mejor?', '["Dominar todas las novedades que aparezcan.","Dominar 2 o 3 herramientas ligadas a tareas reales y revisar su vigencia periódicamente.","Esperar a que las herramientas se estabilicen.","Usar solo las herramientas que recomiende la escuela, aunque no se ajusten a sus tareas reales."]'::jsonb, 1, 'Criterio de selección sobre catálogo: las herramientas cambian rápido.', 'exam'),
('ia-herramientas', 14, 'Un docente reutiliza sin revisar un diálogo de inglés generado por IA y encuentra frases poco naturales. ¿Qué recomienda el curso?', '["Usarlo sin cambios, porque la IA domina los idiomas y sus frases suenan naturales.","No volver a usar IA para idiomas.","Pedir a los estudiantes que lo corrijan sin guía.","Revisar y ajustar el diálogo; la IA ofrece un borrador, no un producto final."]'::jsonb, 3, 'Revisión docente siempre.', 'exam'),
('ia-herramientas', 15, '¿Cuáles son las cuatro categorías de herramientas de IA que organiza el curso?', '["Gratis, de pago, freemium y escolares","Texto, imagen, voz y organización","Celular, computadora, tableta y pizarra digital","Generativa, predictiva, conversacional y analítica"]'::jsonb, 1, 'El curso clasifica las herramientas por lo que generan: texto, imagen, voz y organización. La pregunta clave es ''¿qué necesito generar?''.', 'exam'),
('ia-herramientas', 16, '¿Qué significa que una herramienta sea ''freemium''?', '["Que es totalmente gratuita y sin ningún límite","Que tiene una versión gratuita limitada y una de pago con más funciones","Que es gratuita para docentes y de pago para estudiantes","Que se prueba gratis unos días y después hay que pagar para seguir usándola"]'::jsonb, 1, 'Muchas herramientas ofrecen un plan gratuito real pero limitado. Antes de crear una cuenta, revisa qué incluye exactamente.', 'exam'),
('ia-herramientas', 17, 'Una docente quiere 5 preguntas sobre un cuento para trabajar distintos niveles de comprensión. ¿Qué pide a la IA?', '["Cinco preguntas de respuesta literal sobre los nombres, los lugares y los hechos del cuento","Cinco preguntas de niveles literal, inferencial y crítico a partir del texto pegado","Un resumen del cuento y preguntas sobre ese resumen","Una lista de palabras difíciles del cuento sin preguntas"]'::jsonb, 1, 'Pedir explícitamente los tres niveles de comprensión permite trabajar más que el recuerdo de datos.', 'exam'),
('ia-herramientas', 18, 'Tienes estudiantes que están aprendiendo español como segunda lengua. ¿Qué debes especificar en el prompt?', '["Nada: la IA detecta sola a quién va dirigido el texto","Que el texto sea para estudiantes que aprenden español como segunda lengua y necesitan lenguaje muy sencillo","Que use vocabulario variado para ampliar su léxico","Que el texto sea más largo para que practiquen más"]'::jsonb, 1, 'La IA solo adapta bien si le describes la necesidad. Especificarla evita textos correctos pero inaccesibles para tu grupo.', 'exam'),
('ia-herramientas', 19, 'Pides una imagen para un cartel de primaria baja. ¿Qué detalle mejora más el resultado?', '["Indicar la edad del grupo: colores vivos y formas simples","Pedir un estilo realista y muy detallado, como una fotografía","No dar detalles para que la IA sea más creativa","Pedir que incluya mucho texto dentro de la imagen"]'::jsonb, 0, 'Una misma idea visual debe verse distinta según la edad. Especificar el nivel del grupo da un estilo adecuado.', 'exam'),
('ia-herramientas', 20, '¿Para qué sirve un set de pictogramas coherente en el aula?', '["Para ambientar el aula con un estilo visual uniforme","Para señalizar rincones y rutinas (silencio, turno de hablar), lo que ayuda a anticipar y comprender","Para reemplazar las explicaciones orales del docente","Para estudiantes que todavía no saben leer, en primaria baja; en los demás grados ya no hace falta usarlos"]'::jsonb, 1, 'Los pictogramas consistentes hacen visibles las rutinas: ayudan a todo el grupo y son especialmente útiles para estudiantes con TEA o que están aprendiendo el idioma.', 'exam'),
('ia-herramientas', 21, 'Un docente quiere capturar una idea de planificación mientras va de camino a la escuela. ¿Qué herramienta encaja mejor?', '["Generador de imágenes","Voz a texto (por ejemplo, el dictado del teclado del teléfono)","Una app de presentaciones","Un formulario en línea"]'::jsonb, 1, 'Dictar por voz convierte la idea en texto sin teclear; luego puede organizarla con la IA de texto.', 'exam'),
('ia-herramientas', 22, '¿Qué describe el ''flujo de trabajo completo'' propuesto en el curso?', '["Usar una sola herramienta para todo, sin combinarlas","Dictar ideas, organizarlas con IA de texto, ilustrar con IA de imagen y generar un audio de repaso","Pedir a los estudiantes que hagan el proceso en casa","Comprar una suscripción que incluya todas las funciones"]'::jsonb, 1, 'Combinar voz, texto, imagen y audio de forma encadenada muestra cómo varias herramientas gratuitas pueden cubrir una clase completa.', 'exam'),
('ia-herramientas', 23, '¿Cuál es uno de los errores comunes de quien empieza con herramientas de IA?', '["Dedicar 10 minutos semanales a explorar una función","Esperar un resultado perfecto en el primer intento y abandonar la herramienta","Leer con calma qué incluye el plan gratuito antes de registrarse en la herramienta","Usar una contraseña distinta para cada herramienta"]'::jsonb, 1, 'Lo normal es ajustar y volver a pedir. Esperar perfección al primer intento lleva a abandonar herramientas que sí serían útiles.', 'exam')
INSERT INTO public.exam_questions (course_id, idx, text, options, correct, explanation, source) VALUES
('ia-inclusion', 0, 'Una docente tiene un grupo con estudiantes de niveles de lectura muy distintos y quiere usar el mismo texto base para todos. ¿Cómo puede ayudar la IA?', '["Pidiendo un texto distinto, sobre otro tema, para cada nivel","Generando versiones del mismo texto base adaptadas a cada nivel de lectura","Usando la versión más simple para todo el grupo, para que nadie se quede atrás","Usando la versión más avanzada para todos, para no bajar el nivel"]'::jsonb, 1, 'La IA puede generar rápidamente múltiples versiones adaptadas de un mismo texto base, permitiendo que todos los estudiantes trabajen sobre el mismo tema con el nivel de complejidad apropiado para cada uno — la esencia de la diferenciación pedagógica hecha viable con menos tiempo.', 'lesson'),
('ia-inclusion', 1, '¿Cuál es la diferencia clave entre "simplificar" y "empobrecer" un contenido al usar IA para adaptar material?', '["Son sinónimos: en ambos casos se quitan las palabras difíciles","Simplificar reduce la complejidad del lenguaje manteniendo las ideas esenciales; empobrecer elimina contenido importante en el proceso — el docente debe verificar siempre cuál ocurrió","Simplificar se aplica a matemáticas; empobrecer, a lectura","Simplificar es acortar el texto; empobrecer, quitarle imágenes"]'::jsonb, 1, 'Simplificar bien un texto reduce la complejidad del vocabulario y la estructura sin perder las ideas centrales. Empobrecerlo elimina contenido importante. Solo el docente, con su conocimiento del tema, puede verificar cuál de los dos ocurrió realmente en una adaptación generada por IA.', 'lesson'),
('ia-inclusion', 2, 'Un docente quiere ofrecer opciones de dificultad sin etiquetar públicamente a los estudiantes por su nivel. ¿Cuál es la mejor estrategia?', '["Anunciar en voz alta qué estudiantes deben usar la versión \"fácil\"","Presentar las distintas versiones de la actividad como \"opciones a elegir\" en vez de \"niveles asignados por el docente\"","Usar una sola versión de la actividad para todo el grupo sin excepción","Separar físicamente a los estudiantes según su nivel académico frente a toda la clase"]'::jsonb, 1, 'Ofrecer las versiones diferenciadas como opciones que el estudiante elige, en vez de asignaciones públicas por nivel, preserva la dignidad y motivación de cada estudiante, evitando el estigma de ser etiquetado frente a sus compañeros.', 'lesson'),
('ia-inclusion', 3, 'Según este curso, ¿cuál es el propósito principal de usar IA para la inclusión educativa en contextos con recursos limitados?', '["Asumir que todos los estudiantes tendrán acceso individual a herramientas de IA en casa","Ayudar al docente a preparar más rápido material diferenciado, liberando tiempo para la atención humana directa que realmente sostiene la inclusión","Reemplazar la necesidad de conocer a cada estudiante individualmente","Llevar la IA primero a escuelas urbanas con buena conectividad, y después a las demás"]'::jsonb, 1, 'El enfoque central de este curso es que la IA acelera la preparación docente de material inclusivo y diferenciado, liberando tiempo para la atención humana directa — el verdadero motor de la inclusión educativa — sin asumir que los estudiantes mismos tienen acceso garantizado a estas herramientas.', 'lesson'),
('ia-inclusion', 4, '¿Qué relación propone este curso entre la IA y la tradición de creatividad pedagógica ya existente en las escuelas con recursos limitados?', '["La IA reemplaza esas estrategias tradicionales por otras más eficientes","Se suma a esa tradición, ayudando a documentarla y compartirla más rápido","Esas estrategias tradicionales ya no son necesarias con la llegada de la IA","Son caminos separados: lo tradicional para lo rural y la IA para lo urbano"]'::jsonb, 1, 'Este curso reconoce que la inclusión pedagógica tiene una tradición de creatividad con recursos limitados que precede a la IA. La herramienta se integra a ese trabajo existente como apoyo adicional, no lo sustituye ni lo inicia desde cero.', 'lesson'),
('ia-inclusion', 5, 'Una docente tiene un grupo con niveles de lectura muy distintos. Quiere ofrecer opciones sin que nadie se sienta señalado. ¿Qué es lo más adecuado?', '["Asignar a cada estudiante, en privado, una versión según su nota.","Dar a todos la versión intermedia, para no hacer diferencias.","Formar mesas por nivel para que se ayuden entre pares.","Presentar las versiones como ''opciones de ruta'' disponibles para todos, sin etiquetar niveles."]'::jsonb, 3, 'La diferenciación se normaliza cuando es visible y frecuente para todo el grupo.', 'exam'),
('ia-inclusion', 6, 'Un estudiante con dificultad lectora recibe un texto largo. ¿Qué adaptación con IA conserva el contenido esencial?', '["Un resumen de dos líneas que quite los conceptos difíciles para que no se frustre.","El mismo texto con letra más grande.","Una versión con oraciones más cortas y vocabulario claro, manteniendo las ideas centrales y los términos clave.","Un texto distinto, más corto, sobre un tema relacionado."]'::jsonb, 2, 'Simplificar el lenguaje no es empobrecer el contenido.', 'exam'),
('ia-inclusion', 7, 'Una maestra sospecha que un estudiante tiene TDAH, pero no hay diagnóstico. ¿Qué actitud sigue el curso?', '["Esperar el diagnóstico antes de hacer cualquier ajuste.","Decirle a la familia que tiene TDAH para que lo lleven a tratamiento cuanto antes.","Pedir a la IA una lista de síntomas para confirmar la sospecha.","Empezar con adaptaciones basadas en su observación, como instrucciones en pasos cortos, y coordinar con orientación sin etiquetar."]'::jsonb, 3, 'No hace falta evaluación formal para ajustar la práctica.', 'exam'),
('ia-inclusion', 8, 'Un docente quiere adaptar un examen para un estudiante que necesita más tiempo. ¿Qué es lo más justo?', '["Ajustar los criterios para que el examen sea más fácil de aprobar y no se sienta en desventaja.","Darle el mismo examen sin cambios.","Eximirlo de la evaluación y calificarlo por participación.","Evaluar los mismos aprendizajes, con más tiempo o menos preguntas por sección."]'::jsonb, 3, 'Adaptar el tiempo preserva el estándar y mejora el acceso.', 'exam'),
('ia-inclusion', 9, 'En una escuela rural sin conectividad, una docente quiere hacer inclusión con IA. ¿Qué enfoque es coherente?', '["Renunciar a la inclusión con IA hasta que la escuela tenga internet estable y un dispositivo por estudiante.","Exigir que los estudiantes accedan a IA desde casa.","Usar la IA al preparar materiales fuera de clase y llevarlos impresos, sin exigir acceso a los estudiantes.","Llevar una tableta con IA para que los estudiantes la usen por turnos."]'::jsonb, 2, 'La IA prepara; la atención directa es lo que incluye.', 'exam'),
('ia-inclusion', 10, 'Una docente nota que un estudiante cambió su conducta de forma repentina y parece triste. ¿Qué decisión es más acertada?', '["Pedir a la IA actividades para levantarle el ánimo en clase.","Esperar a que se le pase.","Hablar con él, coordinar con orientación escolar y la familia; la IA no puede atender señales de trauma o duelo.","Cambiarlo de lugar y darle tareas más sencillas mientras se recupera."]'::jsonb, 2, 'Hay necesidades que ninguna herramienta puede atender.', 'exam'),
('ia-inclusion', 11, 'Una maestra necesita explicar a una familia la adaptación de lectura de su hijo. ¿Cómo hacerlo sin estigmatizar?', '["Explicar que su hijo no puede con el nivel del grupo y que por eso necesita una versión distinta y más sencilla de la tarea.","Presentarla como un apoyo para acceder al contenido, destacando sus fortalezas.","Mencionarla solo si la familia pregunta por las notas.","Mostrar sus resultados frente al promedio del grupo."]'::jsonb, 1, 'Comunicar adaptaciones con enfoque de fortalezas.', 'exam'),
('ia-inclusion', 12, 'Un docente probó una adaptación durante un mes y no ve cambios. ¿Qué haría?', '["Mantenerla porque ''ya está decidida''.","Revisar con el estudiante qué le ayuda, ajustar o cambiar la adaptación y registrar el seguimiento.","Retirar la adaptación y volver al material de todo el grupo.","Pedir a la IA una adaptación nueva y aplicarla de inmediato, sin consultar al estudiante ni a la familia."]'::jsonb, 1, 'Una adaptación se evalúa y se ajusta.', 'exam'),
('ia-inclusion', 13, 'Una docente quiere diferenciar una tarea de ciencias sin cambiar su dificultad. ¿Qué opción aplica el principio de diferenciar por producto?', '["Dar a todos la misma hoja y más tiempo a quien lo necesite.","Permitir que cada estudiante demuestre lo aprendido con un cartel, un audio o una explicación oral.","Cambiar la tarea por una más corta para algunos.","Dar una versión con menos preguntas a quienes tienen dificultades."]'::jsonb, 1, 'Diferenciar por producto final respeta intereses y fortalezas.', 'exam'),
('ia-inclusion', 14, 'Un docente quiere diferenciar absolutamente todas sus actividades con IA y termina agotado. ¿Qué recomienda el curso?', '["Elegir sus batallas: diferenciar donde más impacta y apoyarse en el DUA para el resto.","Seguir intentando diferenciar todo.","Dejar de diferenciar por completo.","Pedir a la IA que diferencie todo automáticamente, sin revisar."]'::jsonb, 0, 'No todo necesita diferenciarse.', 'exam'),
('ia-inclusion', 15, '¿Qué propone el Diseño Universal para el Aprendizaje (DUA)?', '["Diseñar una sola versión de la clase y adaptarla después, cuando un estudiante concreto tenga dificultades con ella","Ofrecer desde el inicio varias formas de presentar el contenido, de involucrarse y de demostrar lo aprendido","Separar a los estudiantes con necesidades especiales en un grupo aparte","Usar tecnología digital en todas las clases para llegar a todos"]'::jsonb, 1, 'El DUA anticipa la diversidad: planifica múltiples formas de representación, participación y expresión desde el principio, no como parche posterior.', 'exam'),
('ia-inclusion', 16, 'Una docente explica el mismo concepto de proporciones con ejemplos de fútbol, cocina y música según los intereses de cada grupo. ¿Qué está haciendo?', '["Bajando el nivel de exigencia para los grupos que tienen más dificultades","Diferenciando por interés, sin cambiar el contenido","Evaluando con criterios distintos a cada grupo","Reemplazando el currículo por temas recreativos"]'::jsonb, 1, 'Diferenciar no es solo ''más fácil o más difícil'': también puede adaptarse el contexto a los intereses, manteniendo el mismo aprendizaje.', 'exam'),
('ia-inclusion', 17, '¿Qué fuente de información sobre cómo apoyar a un estudiante se olvida con frecuencia, según el curso?', '["El expediente del año anterior","Preguntarle directamente al propio estudiante qué le ayuda","Los resultados de las pruebas estandarizadas del año anterior","La opinión de sus compañeros de clase"]'::jsonb, 1, 'Muchos estudiantes pueden decir con claridad qué formato les resulta más fácil. Preguntarles es simple y muy informativo.', 'exam'),
('ia-inclusion', 18, 'Un estudiante con baja visión no puede ver bien una infografía que usarás en clase. ¿Qué apoyo puedes preparar con IA?', '["Una descripción textual de la imagen, que pueda leerse o escucharse","Una versión de la infografía con más colores y muchos detalles pequeños","La infografía en blanco y negro, para que tenga menos distracciones","Sentarlo en la primera fila y proyectar la infografía más grande"]'::jsonb, 0, 'Una descripción textual (que también puede convertirse en audio) permite acceder al mismo contenido visual.', 'exam'),
('ia-inclusion', 19, 'Además de texto más grande, ¿qué ajuste de diseño conviene pedir para estudiantes con baja visión?', '["Fondos con imágenes decorativas detrás del texto","Alto contraste entre el texto y el fondo","Letras de estilo cursivo para que se vea más amigable","Colores pastel suaves para texto y fondo"]'::jsonb, 1, 'El alto contraste y el tamaño de letra son ajustes simples que mejoran mucho la lectura para baja visión.', 'exam'),
('ia-inclusion', 20, '¿Qué es un glosario visual de vocabulario y para qué sirve?', '["Una lista de palabras difíciles con su definición del diccionario, para copiar en el cuaderno","Términos clave con una definición breve en lenguaje simple y una imagen para cada uno","Un diccionario completo de la materia para consultar en casa","Un examen de vocabulario con imágenes"]'::jsonb, 1, 'Combinar definición simple e imagen apoya a quienes aprenden el idioma o tienen dificultad lectora, y beneficia al grupo entero.', 'exam'),
('ia-inclusion', 21, '¿Qué debería incluir un borrador simple de plan de apoyo individual generado con IA?', '["El diagnóstico clínico completo del estudiante, redactado por la IA a partir de tus observaciones","Objetivo, adaptaciones concretas y cómo se dará seguimiento, para revisarlo con el equipo","Una comparación de su rendimiento con el promedio del grupo","Los nombres completos y datos médicos del estudiante para que la IA personalice mejor"]'::jsonb, 1, 'El borrador organiza objetivo, adaptaciones y seguimiento. Se escribe sin datos identificables y se revisa con orientación o especialistas.', 'exam'),
('ia-inclusion', 22, 'Un estudiante tiene una necesidad educativa especial diagnosticada. ¿Cómo deben decidirse las adaptaciones curriculares importantes?', '["Las decide el docente con ayuda de la IA, para no recargar al equipo de orientación escolar","Coordinadas con el orientador, el psicólogo escolar o el especialista que corresponda","Las decide la familia sin intervención de la escuela","No se hacen adaptaciones para no dar un trato diferente"]'::jsonb, 1, 'Con un diagnóstico formal, las adaptaciones importantes se coordinan con el equipo especializado. La IA solo ayuda a preparar información.', 'exam'),
('ia-inclusion', 23, '¿Qué efecto tiene normalizar la diferenciación en la cultura del aula?', '["Hace que quienes usan apoyos se sientan señalados","Las distintas formas de trabajar se vuelven parte de la rutina y nadie queda marcado por usarlas","Obliga a dar a todos exactamente la misma tarea","Genera competencia entre los estudiantes por el nivel más difícil"]'::jsonb, 1, 'Cuando hay opciones visibles y frecuentes para todo el grupo, elegir un apoyo deja de ser una etiqueta.', 'exam')
INSERT INTO public.exam_questions (course_id, idx, text, options, correct, explanation, source) VALUES
('ia-ciudadania', 0, '¿Cuál es el argumento principal de este curso a favor de enseñar sobre IA en vez de simplemente prohibirla en el aula?', '["Prohibirla en el aula es la forma más efectiva de proteger el aprendizaje","Los estudiantes ya la usan fuera del aula de todas formas; enseñar criterio de uso responsable es una habilidad más útil y realista que una prohibición difícil de hacer cumplir","Conviene esperar a que el ministerio emita lineamientos antes de mencionarla","Conviene enseñarla primero a los estudiantes de nivel avanzado"]'::jsonb, 1, 'Dado que muchos estudiantes ya interactúan con IA fuera del aula sin ninguna guía, este curso argumenta que enseñar explícitamente el criterio de uso responsable es más efectivo y realista que una prohibición que es difícil de hacer cumplir y no prepara al estudiante para el resto de su vida.', 'lesson'),
('ia-ciudadania', 1, '¿Cuál es una buena actividad de aula para enseñar a los estudiantes a verificar información generada por IA?', '["Mostrar ejemplos de respuestas erróneas de IA para que desconfíen de ella","Pedir que hagan una pregunta a la IA sobre un tema que ya conocen y comparen la respuesta con una fuente confiable, discutiendo las diferencias","Aceptar las respuestas de la IA cuando citan una fuente","Pedir que usen solo libros para que no dependan de la IA"]'::jsonb, 1, 'Comparar activamente una respuesta de IA con una fuente confiable, sobre un tema que el estudiante ya conoce, convierte la verificación de información en un hábito practicado y vivencial, mucho más efectivo que simplemente advertir sobre el riesgo sin ejemplos concretos.', 'lesson'),
('ia-ciudadania', 2, '¿Cuál es un enfoque más efectivo que solo prohibir el uso de IA para evitar copiar en evaluaciones?', '["Revisar cada trabajo con un detector de IA y sancionar los casos positivos","Rediseñar las evaluaciones para requerir conexión con el contexto específico del estudiante y sostener conversaciones sobre por qué la honestidad académica importa para su propio aprendizaje","Pasar todas las evaluaciones a exámenes presenciales de opción múltiple","No mencionar el tema y esperar que los estudiantes decidan solos"]'::jsonb, 1, 'Rediseñar evaluaciones para que requieran aplicación personal y contextual (difícil de resolver solo con una IA genérica), combinado con conversaciones honestas sobre por qué el aprendizaje propio importa, es más efectivo y duradero que solo aumentar prohibiciones o castigos.', 'lesson'),
('ia-ciudadania', 3, '¿Cuál es una regla básica de seguridad digital que debes enseñar explícitamente a tus estudiantes sobre el uso de chats de IA?', '["Es seguro compartir información personal con una IA porque las conversaciones son privadas","Nunca compartir nombre completo, dirección, teléfono ni fotos propias en un chat de IA, igual que en cualquier otra plataforma en línea","Esta regla importa sobre todo a partir de los 15 años, cuando se usan más redes","Los chats de IA son completamente diferentes a las redes sociales en términos de privacidad"]'::jsonb, 1, 'La regla de no compartir información personal identificable aplica a los chats de IA con la misma importancia que a cualquier otra plataforma digital, y debe enseñarse explícitamente y reforzarse con el tiempo, sin asumir que los estudiantes la conocen por sí solos.', 'lesson'),
('ia-ciudadania', 4, 'Al cerrar esta ruta completa sobre IA, ¿cuál es el hilo conductor que conecta los 5 cursos (fundamentos, ahorro de tiempo, herramientas, inclusión y ciudadanía digital)?', '["La IA debe usarse en todos los contextos posibles para no quedarse atrás","La IA es una herramienta poderosa que acelera tareas mecánicas y amplía el acceso, pero el criterio humano —del docente y, con guía, del estudiante— sigue siendo insustituible en las decisiones que realmente importan","La IA debe evitarse en el contexto educativo, porque los riesgos de privacidad, sesgo y dependencia superan cualquier ahorro de tiempo","La IA es útil sobre todo para docentes con formación técnica"]'::jsonb, 1, 'El hilo conductor de toda la ruta es el equilibrio entre aprovechar el poder real de la IA (velocidad, accesibilidad, apoyo a la inclusión) y preservar el criterio humano —pedagógico en el docente, crítico en el estudiante— en las decisiones donde el juicio propio es insustituible.', 'lesson'),
('ia-ciudadania', 5, 'Un docente descubre que varios estudiantes de secundaria ya usan IA para sus tareas. ¿Qué respuesta es más coherente con el curso?', '["Prohibirla en las tareas y bajar puntos a quien la use.","No intervenir, porque el uso de IA en casa no es tema de la escuela.","Abrir una conversación sin juicio, enseñar cómo verificar y citar el uso de IA y rediseñar tareas.","Permitirla solo en tareas de investigación, sin más indicaciones."]'::jsonb, 2, 'Prohibir sin enseñar no evita el uso; enseñar sí forma criterio.', 'exam'),
('ia-ciudadania', 6, 'Una docente quiere que sus estudiantes aprendan a verificar información de IA. ¿Qué actividad es adecuada?', '["Pedir que copien la respuesta de la IA y la comenten en clase.","Mostrar respuestas de la IA y explicar cuáles son correctas.","Pedir que consulten solo la IA para que comparen sus propias respuestas.","Pedir a parejas que hagan la misma pregunta a la IA y a una fuente confiable, y comparar las diferencias."]'::jsonb, 3, 'Contrastar IA y fuente confiable desarrolla pensamiento crítico.', 'exam'),
('ia-ciudadania', 7, 'Un estudiante entrega un trabajo perfecto pero no puede explicarlo. ¿Qué estrategia de integridad académica es más útil?', '["Acusarlo de copiar sin evidencia.","Anular la tarea para todo el grupo.","Pedir evidencia del proceso, como borradores y notas, y una breve explicación oral.","Aceptarlo porque está bien escrito."]'::jsonb, 2, 'El portafolio de proceso evidencia el trabajo propio.', 'exam'),
('ia-ciudadania', 8, 'Una maestra rediseña una tarea de resumen de un libro, porque cualquier IA la resuelve. ¿Qué cambio hace la tarea más a prueba de copiar y pegar?', '["Pedir un resumen más largo.","Pedir que lo hagan en clase, con el libro, sin dispositivos.","Pedir que lo escriban a mano en clase y que entreguen también todos los borradores del proceso.","Pedir una opinión argumentada con ejemplos de la vida del estudiante y una presentación oral."]'::jsonb, 3, 'Tareas que exigen contexto personal y proceso son más difíciles de delegar.', 'exam'),
('ia-ciudadania', 9, 'Una docente quiere que su grupo de primaria entienda qué es la IA en 10 minutos. ¿Qué enfoque es más apropiado?', '["Una clase técnica sobre redes neuronales.","Explicar que la IA es como un buscador muy rápido que encuentra la respuesta correcta en internet.","Una explicación simple con ejemplos: un programa que aprende patrones y a veces falla.","Evitar el tema hasta secundaria."]'::jsonb, 2, 'El contenido se ajusta a la edad.', 'exam'),
('ia-ciudadania', 10, 'Un estudiante comparte con un chatbot su nombre completo, escuela y dirección para ''personalizar'' las respuestas. ¿Qué debió enseñarle el docente?', '["No compartir datos personales con una IA, porque no se sabe cómo se almacenan ni se usan.","Compartir solo el apellido y la ciudad.","Compartirlo si el chatbot es de una empresa conocida.","Compartirlo solo si la IA promete confidencialidad en sus condiciones de uso y privacidad de datos."]'::jsonb, 0, 'Regla básica de seguridad digital.', 'exam'),
('ia-ciudadania', 11, 'Un grupo circula un audio falso de una compañera generado con IA. ¿Qué respuesta del docente es más adecuada?', '["Detener la situación, proteger a la estudiante, aplicar el protocolo escolar y conversar con el grupo sobre el daño y la responsabilidad.","No intervenir, porque ocurrió en redes sociales fuera del horario escolar; le corresponde a la familia resolverlo, no a la escuela ni al docente.","Pedir que no lo vuelvan a hacer sin más consecuencias.","Pedir a la estudiante que ignore el audio hasta que se olvide."]'::jsonb, 0, 'El ciberacoso con IA es un problema de convivencia y protección.', 'exam'),
('ia-ciudadania', 12, 'Un docente nota que un estudiante pregunta a la IA antes de intentar cualquier tarea. ¿Qué intervención es mejor?', '["Prohibirle la IA en todas las clases.","Permitirlo, porque así aprende a usar la tecnología.","Darle tareas que la IA no pueda resolver, sin conversarlo.","Establecer la regla ''primero intento yo, luego consulto'' y pedir que explique su proceso."]'::jsonb, 3, 'Evitar la dependencia excesiva.', 'exam'),
('ia-ciudadania', 13, 'Una docente construye con el grupo un acuerdo de uso de IA. ¿Qué característica lo hace más efectivo?', '["Que lo redacte el docente y lo firmen los estudiantes.","Que sea elaborado y firmado en conjunto, con expectativas claras y consecuencias formativas.","Que sea un texto muy completo, con todas las situaciones posibles.","Que no se mencione el acuerdo hasta que haya un problema, para no darles ideas a los estudiantes."]'::jsonb, 1, 'Los acuerdos construidos en conjunto se respetan más.', 'exam'),
('ia-ciudadania', 14, 'Al cierre del curso, ¿qué hilo conductor une a las cinco rutas de IA?', '["La IA debe reemplazar las tareas mecánicas del docente sin supervisión, para que el ahorro sea completo.","La IA es peligrosa y debe evitarse.","La IA es una herramienta de apoyo cuyo uso responsable depende del criterio pedagógico del docente.","La IA mejora el aprendizaje por sí sola."]'::jsonb, 2, 'Criterio docente en el centro.', 'exam'),
('ia-ciudadania', 15, '¿Qué necesita entender un estudiante de primaria sobre la IA, según el curso?', '["Cómo se programan las redes neuronales","Ideas simples: la IA puede equivocarse y no se le dan datos personales","Que la IA da información correcta si se le pregunta bien","Las diferencias técnicas entre los modelos de IA de las distintas empresas"]'::jsonb, 1, 'El contenido se ajusta a la edad. En primaria bastan dos ideas claves: la IA puede equivocarse y nunca se comparten datos personales.', 'exam'),
('ia-ciudadania', 16, '¿Cuál es una buena forma de iniciar la conversación sobre IA con un grupo?', '["Advertir al inicio que usar IA es hacer trampa","Una pregunta sin juicio: ''¿Alguna vez le has preguntado algo a una IA? ¿Para qué?''","Mostrar noticias alarmantes sobre los peligros de la IA","Pedir que entreguen sus celulares antes de hablar del tema, para que presten toda su atención"]'::jsonb, 1, 'Empezar sin juicio permite que compartan su experiencia real antes de introducir criterios de uso responsable.', 'exam'),
('ia-ciudadania', 17, '¿Qué señal de alerta indica que una respuesta de IA podría estar inventada?', '["Que la respuesta sea corta y sencilla, sin tecnicismos ni explicaciones largas","Una cita o fuente muy específica que no se puede encontrar en ningún lado","Que la respuesta incluya varios ejemplos","Que la respuesta use lenguaje técnico"]'::jsonb, 1, 'Datos muy específicos difíciles de verificar o citas imposibles de encontrar son señales típicas de una ''alucinación''.', 'exam'),
('ia-ciudadania', 18, 'Una IA responde: ''El agua hierve a 100 °C a nivel del mar, y es la mejor forma de purificarla''. ¿Qué habilidad trabaja esta frase?', '["Distinguir un hecho verificable de una opinión o interpretación","Memorizar datos científicos","Comprender cómo funciona por dentro un modelo de lenguaje como este","Traducir información científica"]'::jsonb, 0, 'La primera parte es un hecho verificable; ''la mejor forma'' es una valoración. Separarlos es parte del pensamiento crítico.', 'exam'),
('ia-ciudadania', 19, 'En la actividad ''encuentra el error a propósito'', ¿qué hace el docente?', '["Pide a la IA que revise y corrija los errores de los estudiantes antes de que el docente los vea","Presenta una respuesta de IA con un error deliberado y pide al grupo encontrarlo investigando","Pide a los estudiantes que inventen errores para confundir a la IA","Muestra respuestas correctas de la IA para que las copien"]'::jsonb, 1, 'Buscar un error escondido entrena a verificar con fuentes confiables en vez de aceptar la respuesta por su tono.', 'exam'),
('ia-ciudadania', 20, 'Para un trabajo de investigación serio, ¿qué papel debería tener un resumen generado por IA?', '["Es suficiente como única fuente si el tema es sencillo","Un punto de partida que no reemplaza consultar al menos una fuente primaria o confiable","No debe usarse en ninguna etapa de una investigación seria","Puede citarse como fuente principal si el docente lo revisa"]'::jsonb, 1, 'Un resumen de IA puede orientar, pero la investigación requiere contrastar con fuentes primarias o confiables.', 'exam'),
('ia-ciudadania', 21, '¿Cómo se enseña el uso ético de la IA en trabajos escolares?', '["Pidiendo que no la mencionen, para que el trabajo se valore como propio del estudiante","Pidiendo que declaren cuándo y cómo la usaron, igual que citan un libro","Dejando que cada estudiante decida si lo menciona o no","Restando puntos a todo trabajo donde se usó"]'::jsonb, 1, 'Declarar el uso de IA (para qué y cómo) es parte de la honestidad académica, como citar cualquier otra fuente.', 'exam'),
('ia-ciudadania', 22, '¿Por qué pedir borradores y versiones previas (portafolio de proceso) ayuda a la integridad académica?', '["Porque aumenta la cantidad de tareas que el docente puede calificar en el periodo","Porque da evidencia natural del proceso de pensamiento propio del estudiante","Porque impide técnicamente el uso de la IA","Porque reemplaza la necesidad de evaluar el producto final"]'::jsonb, 1, 'Los borradores muestran cómo evolucionó el trabajo; esa evidencia del proceso es difícil de fabricar con un solo copiar y pegar.', 'exam'),
('ia-ciudadania', 23, '¿Qué diferencia propone el curso entre un uso sano de la IA y la dependencia excesiva?', '["Usarla en casa para las tareas escolares, pero nunca durante la clase con el docente","Intentar primero por uno mismo y luego usar la IA para revisar o ampliar","Usarla en materias de ciencias, no en las de lenguaje","Limitar el tiempo de uso a una hora por semana"]'::jsonb, 1, 'Si el estudiante pide ayuda antes de intentar, deja de practicar la habilidad que la tarea buscaba desarrollar.', 'exam')
INSERT INTO public.exam_questions (course_id, idx, text, options, correct, explanation, source) VALUES
('manejo-conductas', 0, 'Según la idea de Ross Greene "los niños se portan bien si pueden", ¿cómo debería interpretarse mejor una conducta desafiante recurrente?', '["Como una decisión deliberada del estudiante de desobedecer","Como una señal de que el estudiante aún no tiene desarrollada la habilidad necesaria para manejar esa situación específica, más que como falta de voluntad","Como un problema de crianza que debe resolverse sobre todo en casa","Como algo que se corrige aumentando la consecuencia hasta que se detenga"]'::jsonb, 1, 'Este enfoque, respaldado por investigación en psicología del desarrollo, propone que la conducta desafiante recurrente suele reflejar una habilidad de autorregulación, comunicación o manejo de frustración que el estudiante aún no domina, más que una elección deliberada de desobedecer.', 'lesson'),
('manejo-conductas', 1, 'Un estudiante grita y desafía al docente frente a la clase. ¿Cuál es la primera acción recomendada por este curso, antes de cualquier consecuencia?', '["Responder con voz firme y alta para dejar claro de inmediato quién conduce la clase y que esa conducta no se acepta","El docente regula su propia respuesta emocional primero (respirar, bajar el tono), ya que un adulto desregulado no puede ayudar a un estudiante a regularse","No responder en el momento y seguir con la clase, para no darle protagonismo frente al grupo","Pedirle que salga del aula hasta que se calme y hablar con él al final de la jornada"]'::jsonb, 1, 'La autorregulación del docente es el primer paso porque dos personas alteradas se alimentan mutuamente en una escalada. Responder desde la calma —no desde la reacción— es lo que permite manejar la situación con eficacia real.', 'lesson'),
('manejo-conductas', 2, '¿Por qué las normas de aula construidas junto con los estudiantes tienden a respetarse más que las impuestas por el docente?', '["Porque son normas más flexibles y por eso es más fácil cumplirlas","Porque el proceso de construirlas juntos genera un compromiso genuino con algo que los estudiantes ayudaron a crear, en vez de una regla externa impuesta","Porque los estudiantes temen más la sanción que pusieron sus propios compañeros","Porque al estar escritas con palabras de los propios estudiantes, se entienden mejor, aunque el compromiso que generan sea el mismo que con las impuestas por el docente"]'::jsonb, 1, 'La investigación en gestión de aula muestra que la participación en la construcción de normas genera un sentido de pertenencia y compromiso que una norma impuesta desde afuera no logra, incluso cuando el contenido de la norma es similar.', 'lesson'),
('manejo-conductas', 3, '¿Cuál es la ventaja principal de reconocer las señales tempranas de escalada en un estudiante (tensión corporal, silencio repentino, respiración acelerada)?', '["Permite aplicar la consecuencia antes de que la conducta empeore","Da una ventana para intervenir con calma antes de que la situación escale","Permite registrar las señales en el expediente para justificar una sanción más fuerte si se repite","Permite avisar a la familia a tiempo para que intervenga desde casa"]'::jsonb, 1, 'Detectar señales tempranas permite una intervención preventiva y calmada —una pregunta, un momento de pausa, un cambio de actividad— en vez de reaccionar solo cuando la conducta ya escaló a su punto más difícil de contener.', 'lesson'),
('manejo-conductas', 4, '¿Qué es la "co-regulación" en el manejo de conducta desafiante?', '["Pedir a otro estudiante cercano que ayude a calmar al que está desregulado","El proceso por el cual la calma del adulto (voz, postura, respiración) ayuda al estudiante a bajar de intensidad, antes de cualquier conversación","Explicarle con calma, en ese momento, por qué su conducta no es aceptable y qué consecuencia tendrá","Dejar al estudiante a solas hasta que se calme, para no reforzar la conducta con atención, y luego aplicar la consecuencia que corresponda según el reglamento"]'::jsonb, 1, 'La co-regulación se basa en que un estudiante desregulado no puede razonar en ese momento; necesita primero la calma prestada de un adulto cercano para bajar su nivel de activación, antes de poder procesar cualquier conversación o consecuencia.', 'lesson'),
('manejo-conductas', 5, '¿Por qué ofrecer "opciones limitadas" (por ejemplo, dos alternativas aceptables para el docente) suele funcionar mejor que dar una orden absoluta a un estudiante desregulado?', '["Porque así el estudiante decide qué hacer y el docente evita una confrontación, aceptando cualquier opción que elija","Porque devuelve al estudiante una sensación de control dentro de un límite ya definido por el docente, reduciendo la resistencia que genera una orden absoluta","Porque permite al docente ganar tiempo mientras decide qué consecuencia aplicar después","Porque al tener opciones el estudiante se distrae y olvida el motivo de su enojo"]'::jsonb, 1, 'Las opciones limitadas mantienen el límite (ambas opciones son aceptables para el docente) mientras devuelven al estudiante una sensación de autonomía, lo cual reduce la resistencia típica ante una orden absoluta que no deja ningún espacio de decisión.', 'lesson'),
('manejo-conductas', 6, '¿Cuál es la diferencia clave entre una "consecuencia lógica" y un "castigo arbitrario"?', '["Ambos son sanciones; la diferencia es solo que la consecuencia lógica se anuncia antes y el castigo después de la conducta","La consecuencia lógica se relaciona con la conducta (recoger lo que se tiró); el castigo no, y por eso enseña menos","El castigo arbitrario es más claro para el estudiante porque no da lugar a discusión","La consecuencia lógica se aplica en privado y el castigo frente al grupo"]'::jsonb, 1, 'Las consecuencias lógicas, al estar directamente relacionadas con la conducta, ayudan al estudiante a entender el impacto real de sus acciones y qué hacer distinto. Los castigos arbitrarios, al no tener esa conexión, generan más resentimiento que aprendizaje.', 'lesson'),
('manejo-conductas', 7, '¿Por qué reconocer los límites de tu rol docente (y derivar casos que requieren apoyo especializado) es parte responsable del manejo de conducta, y no un fracaso?', '["Porque un docente de aula no tiene tiempo para atender conductas difíciles además de enseñar","Porque situaciones como trauma severo, autolesión o abuso requieren apoyo especializado, y derivarlas a tiempo protege al estudiante","Porque derivar demuestra que se agotaron todas las opciones, así que conviene intentar resolver primero cualquier situación —incluso trauma o autolesión— dentro del aula antes de pedir apoyo","Porque los psicólogos deben encargarse de los estudiantes con conductas desafiantes"]'::jsonb, 1, 'Un manejo de conducta responsable incluye reconocer cuándo una situación requiere apoyo especializado que va más allá de lo que un docente, sin formación clínica, puede manejar solo. Derivar a tiempo es una decisión profesional, no una falla.', 'lesson'),
('manejo-conductas', 8, 'Un estudiante grita y lanza su cuaderno. La docente siente que se le acelera el pulso. ¿Qué es lo primero que recomienda el curso?', '["Hablar más fuerte para recuperar el control del grupo.","Regular su propia calma con una respiración y bajar el tono antes de intervenir.","Enviar al estudiante a dirección de inmediato.","Seguir con la clase y hablar con él al final."]'::jsonb, 1, 'La co-regulación empieza por la calma del adulto.', 'exam'),
('manejo-conductas', 9, 'Un estudiante que siempre entrega tarde dice ''no quiero hacerla''. Según Ross Greene, ¿qué hipótesis conviene explorar primero?', '["Que es falta de esfuerzo y necesita una consecuencia firme.","Que busca llamar la atención y conviene no responderle para que no lo repita.","Que en casa no hay rutinas y hay que hablar con la familia.","Que quizá no puede hacerla por una habilidad o circunstancia pendiente, y averiguar qué le dificulta."]'::jsonb, 3, '''No puede'' antes que ''no quiere''.', 'exam'),
('manejo-conductas', 10, 'Un estudiante se niega a sentarse. La docente le ordena frente al grupo: ''Siéntate ahora''. Él se pone más desafiante. ¿Qué alternativa es más efectiva?', '["Repetir la orden con voz más firme.","Amenazar con bajarle la nota.","Pedir que otro estudiante lo convenza de sentarse, porque la presión de los compañeros suele funcionar mejor que la del docente.","Acercarse y ofrecer dos opciones aceptables en privado: ''Puedes sentarte aquí o junto a la ventana''."]'::jsonb, 3, 'Opciones limitadas y evitar el espectáculo público.', 'exam'),
('manejo-conductas', 11, 'Después de una crisis, un estudiante ya está calmado. ¿Cuál es el momento adecuado para la conversación de reparación?', '["Cuando ambos están tranquilos, en privado, enfocándose en qué ocurrió y cómo reparar.","En el momento de la crisis, para que relacione la conducta con su efecto.","Frente al grupo, para que su caso sirva de ejemplo y los demás entiendan las consecuencias.","Al día siguiente, por escrito, para que no se repita la tensión."]'::jsonb, 0, 'La reparación requiere calma y privacidad.', 'exam'),
('manejo-conductas', 12, 'Una estudiante rompe la regla de no usar el celular. Dos docentes proponen: (A) quitarle el celular y bajarle la nota de la semana; (B) guardarlo hasta el final de la clase. ¿Cuál es una consecuencia lógica?', '["La B, porque está conectada con la conducta y es proporcional.","La A, porque es más firme y desalienta que se repita.","Ambas, siempre que se apliquen de inmediato.","La A, porque la nota es lo que más le importa y así no vuelve a pasar."]'::jsonb, 0, 'Consecuencia lógica: relacionada, respetuosa y razonable.', 'exam'),
('manejo-conductas', 13, 'Una docente llama a la familia de un estudiante: ''Su hijo es un problema''. ¿Cómo debió formular el contacto?', '["Enviar una nota con el registro de faltas del mes.","Pedir a la familia que imponga un castigo en casa.","Describir la conducta observada, mostrar interés en su bienestar y buscar acuerdos en conjunto.","Esperar a acumular varias situaciones para tener evidencia y luego llamar."]'::jsonb, 2, 'Trabajar con la familia sin culpar.', 'exam'),
('manejo-conductas', 14, 'Un estudiante presenta conductas agresivas persistentes, señales de abandono y no mejora con las estrategias del aula. ¿Qué corresponde?', '["Seguir intentando con más disciplina y consecuencias antes de derivar, para no perder autoridad ante el grupo.","Cambiarlo de grupo para que empiece de cero con otro docente.","Reconocer los límites de su rol, documentar y coordinar con orientación y las instancias de protección.","Esperar a que termine el año y dejarlo anotado para el próximo docente."]'::jsonb, 2, 'Hay situaciones que requieren apoyo profesional.', 'exam'),
('manejo-conductas', 15, '¿Qué representa la imagen del ''iceberg de la conducta''?', '["Que las conductas desafiantes son raras y aisladas","Que lo visible es la punta: debajo hay una causa, como frustración, hambre o problemas en casa","Que la mayoría de las conductas tiene una sola causa, la que se ve","Que las conductas graves aparecen sin ninguna señal previa"]'::jsonb, 1, 'La conducta visible tiene causas no visibles. Buscar esa causa orienta una intervención que funciona.', 'exam'),
('manejo-conductas', 16, '¿De dónde viene la palabra ''disciplina'' y qué implica para el aula?', '["De ''castigo'': disciplinar es aplicar sanciones firmes cada vez que se rompe una norma","De ''discípulo'': disciplinar es enseñar una habilidad que falta","De ''control'': disciplinar es mantener el orden del grupo","De ''obediencia'': disciplinar es que se cumplan las normas"]'::jsonb, 1, 'Disciplinar bien es enseñar a regularse, esperar o resolver conflictos, no solo castigar.', 'exam'),
('manejo-conductas', 17, '¿En qué momentos ocurre gran parte de la conducta desafiante, según el curso?', '["Durante los exámenes escritos, cuando están bajo presión por la nota","En las transiciones sin estructura: entrar al aula, cambiar de actividad, terminar antes","Al final de la jornada, cuando el grupo está cansado","Los lunes, después del fin de semana"]'::jsonb, 1, 'Las transiciones poco estructuradas generan conflictos. Una rutina predecible los reduce.', 'exam'),
('manejo-conductas', 18, '¿Qué es el ''reservorio de confianza''?', '["Un registro escrito de las faltas de cada estudiante","La relación positiva que se construye con interacciones cotidianas y que sostiene los límites firmes","Un sistema de puntos canjeables por premios que el docente va acumulando para cada estudiante del grupo","El tiempo libre que se da como recompensa"]'::jsonb, 1, 'Cada saludo genuino o logro reconocido suma confianza. Sin esa relación, un límite firme se vive como ataque.', 'exam'),
('manejo-conductas', 19, 'Dos estudiantes chocan todo el tiempo porque se sientan juntos junto a una zona de paso estrecha. ¿Qué estrategia preventiva aplica?', '["Sancionar a ambos cada vez que discutan, para que aprendan a respetarse entre ellos","Ajustar el ambiente físico: cambiar la ubicación y despejar la zona de tránsito","Hablar con los dos para que firmen un acuerdo de convivencia","Pedir a la familia que hable con ellos"]'::jsonb, 1, 'La disposición del aula influye en la conducta. A veces cambiar el espacio previene conflictos sin necesidad de sanciones.', 'exam'),
('manejo-conductas', 20, 'Un estudiante hace un comentario fuera de lugar para llamar la atención. Es menor y no afecta a nadie. ¿Qué suele funcionar?', '["Detener la clase y confrontarlo frente al grupo para que todos vean que no se permite","No darle atención en el momento y reconocer luego su conducta positiva","Enviarlo a la dirección de inmediato","Pedirle que repita el comentario para todo el grupo"]'::jsonb, 1, 'Muchas conductas menores para buscar atención se apagan si no se refuerzan; reconocer después lo positivo fortalece lo que sí quieres ver.', 'exam'),
('manejo-conductas', 21, '¿Por qué conviene evitar confrontar a un estudiante frente a toda la clase?', '["Porque el docente puede perder el control de la clase","Porque activa su necesidad de ''salvar la cara'' y lo manejable se vuelve una lucha de poder","Porque el reglamento escolar lo desaconseja","Porque el estudiante pierde el respeto por el docente"]'::jsonb, 1, 'Frente al público, ceder se siente como perder. Una conversación privada y breve suele resolverlo mejor.', 'exam'),
('manejo-conductas', 22, '¿Cómo debería usarse un ''tiempo fuera''?', '["Como una consecuencia visible para que todo el grupo vea que la conducta inadecuada tiene costo","Como un espacio breve para recuperar la calma, lejos del estímulo, presentado sin humillar","Como una salida del aula por el resto del día para que reflexione solo","Como un tiempo fijo de 10 minutos, aunque ya se haya calmado"]'::jsonb, 1, 'Bien usado, el tiempo fuera es una herramienta de regulación, no una expulsión disfrazada.', 'exam'),
('manejo-conductas', 23, '¿Para qué sirve documentar los incidentes de un mismo estudiante a lo largo del tiempo?', '["Para tener pruebas si la familia reclama","Para descubrir patrones (hora, actividad, desencadenante) que la memoria sola no capta","Para informar a la familia con detalle cada semana","Para comparar a los estudiantes entre sí"]'::jsonb, 1, 'Un registro simple (fecha, qué pasó, qué lo desencadenó) revela patrones que permiten prevenir y planificar apoyos.', 'exam')
INSERT INTO public.exam_questions (course_id, idx, text, options, correct, explanation, source) VALUES
('sel-docentes', 0, '¿Cuáles son las cinco competencias del marco de aprendizaje socioemocional (SEL) según CASEL?', '["Atención, memoria, motivación, empatía y disciplina","Autoconciencia, autorregulación, conciencia social, habilidades relacionales y toma de decisiones responsable","Autoestima, resiliencia, liderazgo, creatividad y comunicación","Inteligencia interpersonal, intrapersonal, lingüística, lógica y musical"]'::jsonb, 1, 'El marco de CASEL, referencia internacional en SEL, organiza el desarrollo socioemocional en estas cinco competencias interrelacionadas, que juntas forman la base de la inteligencia emocional aplicada al contexto educativo.', 'lesson'),
('sel-docentes', 1, '¿Por qué se dice que "el cerebro emocional va antes que el cognitivo" en el aprendizaje?', '["Porque las emociones se procesan más rápido que las ideas","Porque un estudiante con miedo o desregulado prioriza su seguridad emocional, y atender eso es condición previa para aprender","Porque los estudiantes más emocionales necesitan otro tipo de enseñanza","Porque el SEL debe enseñarse antes que cualquier otra materia en el horario escolar"]'::jsonb, 1, 'Cuando el cerebro está en un estado de alerta o amenaza emocional, prioriza recursos para la supervivencia sobre el razonamiento complejo. Por eso el bienestar emocional no compite con el aprendizaje académico: es su condición habilitante.', 'lesson'),
('sel-docentes', 2, '¿Por qué es valioso ampliar el vocabulario emocional de los estudiantes más allá de "bien" y "mal"?', '["Ninguno: basta con que digan si están bien o mal; profundizar le corresponde al psicólogo escolar","Les permite reconocer y nombrar lo que sienten, en vez de expresarlo solo con la conducta","Sirve sobre todo en secundaria, cuando ya pueden reflexionar","Ayuda a la clase de lenguaje porque amplía el vocabulario general"]'::jsonb, 1, 'Un vocabulario emocional más amplio permite a los estudiantes identificar y comunicar estados internos específicos (frustración, ansiedad, decepción), lo cual reduce la necesidad de expresar esas emociones únicamente a través de conductas difíciles de interpretar.', 'lesson'),
('sel-docentes', 3, '¿Cuál es el efecto de que un docente verbalice su propia regulación emocional frente a sus estudiantes (por ejemplo, "estoy sintiendo frustración, voy a respirar antes de responder")?', '["Hace que los estudiantes perciban al docente como alguien inseguro","Modela la autorregulación: los estudiantes aprenden más del ejemplo que de una explicación","Ayuda al docente a calmarse, pero no influye en los estudiantes","Es mejor hacerlo en privado, porque mostrar emociones frente al grupo le resta autoridad al docente"]'::jsonb, 1, 'El modelado es una de las formas más poderosas de enseñanza socioemocional: observar a un adulto de confianza nombrar y manejar su propia emoción de forma visible da a los estudiantes un ejemplo concreto y replicable de la habilidad.', 'lesson'),
('sel-docentes', 4, '¿Cuál es una forma efectiva de practicar activamente la conciencia social en el aula?', '["Pedir que lean textos sobre la empatía y hagan un resumen","Preguntar directamente \"¿cómo crees que se sintió tu compañero?\" o analizar las emociones de un personaje en una lectura, para entrenar la capacidad de entender la perspectiva de otros","Pegar en el aula carteles con frases sobre el respeto","Dedicar al tema una actividad especial al año, en una efeméride"]'::jsonb, 1, 'La conciencia social se fortalece con práctica activa y regular, no solo con el paso del tiempo. Preguntas que invitan a considerar la perspectiva de otros entrenan esta habilidad de forma concreta y repetible.', 'lesson'),
('sel-docentes', 5, 'Según este curso, ¿cuál es la estrategia más efectiva para prevenir el bullying a largo plazo?', '["Aplicar reglas estrictas de ''no molestar'' con sanciones claras y visibles para cada falta","Construir activamente la capacidad de empatía y perspectiva del otro, combinado con límites claros cuando ya ocurrió una agresión","Dejar que los estudiantes resuelvan sus conflictos por sí mismos para que ganen autonomía","Separar físicamente a los estudiantes que no se llevan bien de forma permanente"]'::jsonb, 1, 'La prevención más duradera combina el desarrollo activo de la empatía (que reduce la probabilidad de que ocurra la agresión) con límites firmes y consecuencias claras cuando la agresión ya sucedió — ambos elementos son necesarios, ninguno sustituye al otro.', 'lesson'),
('sel-docentes', 6, '¿Cuál es la mejor forma de integrar el SEL en el trabajo diario de aula, según este curso?', '["Reservar una hora semanal exclusiva para ''emociones'', separada del resto del currículo, con actividades propias","Tejerlo dentro del contenido académico que ya se enseña (analizar emociones de personajes históricos, motivaciones de personajes de lectura, tolerancia a la frustración en matemáticas)","Dejarlo para el área de orientación, que tiene la formación para trabajarlo","Trabajarlo intensamente en las primeras semanas del año para establecer el clima del grupo"]'::jsonb, 1, 'Integrar el SEL dentro del contenido académico existente, en vez de tratarlo como una materia aparte, permite desarrollarlo sin competir por tiempo con el programa curricular — de hecho, lo fortalece.', 'lesson'),
('sel-docentes', 7, '¿Qué tipo de señales indican, de forma práctica y observable, que el trabajo de SEL está teniendo impacto en un grupo?', '["Una mejora visible en las calificaciones del grupo en las semanas siguientes","Cambios graduales: menos conflictos repetidos, más escucha en las discusiones y estudiantes que nombran lo que sienten","Que los estudiantes dejen de mostrar emociones negativas en clase","Que el grupo obtenga buenos resultados en un cuestionario estandarizado"]'::jsonb, 1, 'El impacto del SEL se observa en cambios conductuales y relacionales graduales —no en un salto dramático inmediato— que reflejan un desarrollo genuino de las competencias socioemocionales a lo largo del tiempo.', 'lesson'),
('sel-docentes', 8, 'Una docente de matemáticas piensa que el SEL le quitará tiempo del currículo. ¿Qué respuesta del curso es más precisa?', '["Tiene razón; el SEL requiere una hora diaria aparte y no puede combinarse con otras asignaturas.","Tiene razón en parte: conviene dejar el SEL para el área de orientación escolar.","El SEL se puede integrar en las clases, por ejemplo con trabajo colaborativo y un checkpoint breve, sin una materia aparte.","El SEL puede esperar a que terminen las evaluaciones del periodo."]'::jsonb, 2, 'SEL no es una materia aparte.', 'exam'),
('sel-docentes', 9, 'Al comenzar la clase, un estudiante dice que ''está bien'' pero se ve alterado. ¿Qué práctica ayuda más a ampliar el vocabulario emocional?', '["Decirle que se nota que no está bien y pedirle que lo cuente.","No preguntar más, para respetar su espacio.","Pedirle que puntúe su ánimo del 1 al 10.","Ofrecer una rueda de emociones y preguntar con más matices: ¿frustrado, cansado, preocupado?"]'::jsonb, 3, 'Enseñar vocabulario emocional.', 'exam'),
('sel-docentes', 10, 'Una maestra implementa SEL con entusiasmo las dos primeras semanas y luego lo abandona. ¿Qué estrategia ayuda a sostener el hábito?', '["Aumentar las actividades de SEL cada semana para mantener el interés y la novedad del grupo durante todo el año.","Esperar a una nueva capacitación.","Dejar que los estudiantes lo organicen solos.","Elegir una rutina pequeña y sostenible, como un checkpoint de 2 minutos, y revisar su efecto periódicamente."]'::jsonb, 3, 'Sostener el hábito exige rutinas pequeñas.', 'exam'),
('sel-docentes', 11, 'Dos estudiantes discuten por un material. ¿Qué paso de mediación entre pares propone el curso?', '["Invitar a cada uno a contar su versión sin interrumpir y buscar juntos una solución.","Decidir quién tiene la razón según lo que vio el docente, y cerrar el tema con una advertencia para ambos.","Separarlos permanentemente.","Pedir al grupo que vote quién tiene razón."]'::jsonb, 0, 'Mediación simple: escuchar y co-construir.', 'exam'),
('sel-docentes', 12, 'Una docente quiere saber si el SEL funciona en su grupo. ¿Qué indicador es más realista?', '["Observar cambios en conflictos, participación y clima, y registrarlos de forma simple.","Aplicar una prueba psicológica estandarizada al inicio y al final del año a todos los estudiantes.","Contar cuántas actividades hizo.","Esperar a que la dirección lo evalúe."]'::jsonb, 0, 'Qué observar para medir el impacto.', 'exam'),
('sel-docentes', 13, 'Durante una actividad grupal, solo dos estudiantes hablan y el resto observa. ¿Cómo ayuda el SEL a mejorar la dinámica?', '["Dejar que los más hábiles lideren el trabajo, porque así el producto final sale mejor.","Cambiar a trabajo individual para que cada uno participe.","Asignar roles rotativos y enseñar normas de escucha para que todos participen.","Dar puntos extra a quien participe más."]'::jsonb, 2, 'El trabajo colaborativo es práctica de SEL.', 'exam'),
('sel-docentes', 14, 'Una docente nota que las niñas del grupo asumen siempre las tareas de cuidado (ordenar, repartir). ¿Qué acción corresponde al enfoque de equidad del curso?', '["Dejar que cada una elija lo que quiera.","Asignar las tareas según quien termina primero.","No intervenir, porque es una decisión de los estudiantes y cada quien debe elegir su papel.","Rotar las responsabilidades entre todos y conversar sobre los roles de género."]'::jsonb, 3, 'Equidad de género en la conciencia social.', 'exam'),
('sel-docentes', 15, '¿Cuáles son las cinco competencias del aprendizaje socioemocional?', '["Atención, memoria, motivación, empatía y disciplina","Autoconciencia, autorregulación, conciencia social, relaciones y decisiones responsables","Autoestima, resiliencia, liderazgo, creatividad y comunicación","Las inteligencias interpersonal, intrapersonal, lingüística, lógico-matemática y musical"]'::jsonb, 1, 'Son las cinco competencias del marco SEL más usado (CASEL), que el curso trabaja módulo por módulo.', 'exam'),
('sel-docentes', 16, '¿Qué encontró el metaanálisis de Durlak et al. (2011) sobre los programas de SEL bien implementados?', '["Que mejoran la conducta, pero no tienen efecto en el rendimiento académico","Que mejoran las habilidades socioemocionales, la conducta y también el rendimiento académico","Que funcionan solo cuando los aplica un psicólogo","Que reemplazan la necesidad de enseñar contenidos académicos, porque el bienestar es lo que más importa"]'::jsonb, 1, 'Con más de 200,000 estudiantes, el metaanálisis mostró mejoras en habilidades, conducta y rendimiento académico.', 'exam'),
('sel-docentes', 17, '¿Cuál es la diferencia entre SEL explícito e implícito?', '["El explícito es para primaria y el implícito para secundaria","El explícito se planifica (un círculo, una lección); el implícito es el clima que creas a diario","El explícito se evalúa con nota y el implícito no","El explícito lo hace el psicólogo y el implícito el docente"]'::jsonb, 1, 'Ambos importan: lo que planificas y lo que modelas a diario en cómo manejas conflictos y emociones.', 'exam'),
('sel-docentes', 18, 'Un docente hace un círculo de SEL una semana y luego lo abandona por un mes. ¿Qué error comete?', '["Hacer el círculo demasiado corto, porque el SEL necesita al menos una hora semanal completa","Ser inconsistente: el SEL necesita prácticas sostenidas para tener efecto","Hacer el círculo con todo el grupo en lugar de en equipos pequeños","No calificar la participación en el círculo"]'::jsonb, 1, 'La inconsistencia es uno de los errores comunes. Pocas prácticas sostenidas en el tiempo funcionan mejor que muchas esporádicas.', 'exam'),
('sel-docentes', 19, '¿Para qué sirve un ''checkpoint emocional'' de 2 o 3 minutos al inicio de la clase?', '["Para calificar la actitud de cada estudiante","Saber cómo llega el grupo para ajustar la clase, y que practiquen nombrar su emoción","Para que cuenten sus problemas personales frente al grupo","Para reemplazar la tutoría con el orientador"]'::jsonb, 1, 'Una palabra, un color o un número del 1 al 5 da información rápida al docente y entrena la autoconciencia.', 'exam'),
('sel-docentes', 20, '¿Cómo debería funcionar un rincón de calma?', '["Como un lugar al que se envía al estudiante que se porta mal, hasta que esté listo para pedir disculpas al grupo","Como un espacio al que el estudiante va de forma voluntaria y breve para regularse, con normas claras","Como un espacio de juego libre sin límite de tiempo","Como un espacio para estudiantes con diagnóstico de TEA o TDAH"]'::jsonb, 1, 'Si se usa como castigo pierde su función. Es una herramienta de autorregulación, de uso voluntario y breve.', 'exam'),
('sel-docentes', 21, 'Una docente se da cuenta de que se tensa mucho cada vez que la interrumpen. ¿Qué práctica del curso aplica?', '["Conocer sus propios disparadores emocionales para anticipar su reacción","Establecer una sanción clara para las interrupciones para que dejen de pasar","Evitar las discusiones en clase para no tensarse","Contener lo que siente para que el grupo no lo note"]'::jsonb, 0, 'Identificar qué situaciones te generan más tensión permite preparar una respuesta regulada en vez de reaccionar.', 'exam'),
('sel-docentes', 22, '¿Qué propone el curso para prevenir el acoso escolar además de la regla ''no molestar a otros''?', '["Más vigilancia y cámaras en el aula, con sanciones ejemplares para quien moleste","Construir activamente empatía y la capacidad de ponerse en el lugar del otro","Separar a los estudiantes por grupos de amigos","Dejar que los estudiantes resuelvan solos sus conflictos"]'::jsonb, 1, 'La prevención más efectiva combina normas claras con trabajo activo de empatía y conciencia social.', 'exam'),
('sel-docentes', 23, 'Antes de una decisión, un estudiante se pregunta ''¿qué pasa si hago esto?, ¿cómo afecta a otros?, ¿hay una mejor opción?''. ¿Qué competencia practica?', '["Autoconciencia","Toma de decisiones responsable","Conciencia social","Escucha activa y empatía con los demás"]'::jsonb, 1, 'Esa pausa breve antes de actuar es el núcleo de la toma de decisiones responsable.', 'exam')
INSERT INTO public.exam_questions (course_id, idx, text, options, correct, explanation, source) VALUES
('comunicacion-asertiva', 0, '¿Cuál de las siguientes opciones es un ejemplo de comunicación asertiva frente a un estudiante que interrumpe constantemente?', '["\"No importa, sigue\", para no cortar el ritmo de la clase","\"¡Ya basta! Siempre haces lo mismo, me tienes cansado\"","\"Necesito que esperes tu turno para hablar. Cuando interrumpes, es difícil que todos aprendamos.\"","\"Si vuelves a interrumpir, te bajo puntos de participación.\""]'::jsonb, 2, 'La respuesta asertiva comunica el límite con claridad y firmeza ("necesito que esperes tu turno"), explica el impacto de la conducta sin atacar la identidad del estudiante, y mantiene el respeto en ambas direcciones.', 'lesson'),
('comunicacion-asertiva', 1, '¿Cuál es la estructura de un "mensaje en primera persona" (mensaje yo) para comunicar asertivamente una necesidad?', '["\"Tú siempre haces esto mal y debes cambiar de inmediato\"","\"Cuando pasa [conducta específica], yo siento/necesito [experiencia propia], y me gustaría [petición concreta]\"","\"Por favor, compórtate como se espera\", sin decir qué conducta ni por qué","Comparar la conducta actual con la de otro estudiante que se porta mejor"]'::jsonb, 1, 'El mensaje en primera persona describe la conducta específica, la experiencia o necesidad propia, y una petición concreta — sin atacar la identidad de la otra persona, lo cual reduce la defensividad y facilita una respuesta constructiva.', 'lesson'),
('comunicacion-asertiva', 2, '¿Qué es "parafrasear" como técnica de escucha activa?', '["Repetir exactamente palabra por palabra lo que dijo la otra persona","Repetir con tus propias palabras lo que escuchaste, para confirmar que entendiste correctamente antes de responder","Resumir lo que dijo y dar de inmediato tu opinión sobre el tema","Hacer una pregunta tras otra para obtener todos los detalles"]'::jsonb, 1, 'Parafrasear con las propias palabras confirma la comprensión, muestra a la otra persona que fue escuchada genuinamente, y reduce malentendidos antes de avanzar hacia una solución.', 'lesson'),
('comunicacion-asertiva', 3, '¿Por qué es importante validar la emoción de un estudiante antes de proponer una solución al conflicto?', '["No es necesario; lo que calma es tener una solución rápida","Porque si la emoción no se valida primero, la persona no se siente escuchada y es menos probable que acepte la solución","Porque validar la emoción significa estar de acuerdo con la conducta que resultó de ella","Es necesario sobre todo en primaria; con adolescentes conviene ir directo a la solución para que asuman su responsabilidad en el conflicto"]'::jsonb, 1, 'Validar la emoción ("veo que esto te frustró") antes de resolver el problema reconoce la experiencia de la persona sin necesariamente aprobar su conducta, lo cual facilita que la solución posterior sea recibida con menos resistencia.', 'lesson'),
('comunicacion-asertiva', 4, '¿Cuál es la diferencia principal entre el rol de "facilitador" y el rol de "juez" en una mediación de conflicto entre estudiantes?', '["El facilitador decide quién tiene la razón tras escuchar; el juez deja que lo resuelvan solos","El facilitador ayuda a que ambas partes se escuchen y lleguen juntas a una solución; el juez decide solo quién tiene la razón","El juez resuelve más rápido y con más claridad, por eso es el rol que conviene en la mayoría de los conflictos escolares del día a día","El facilitador es otro estudiante y el juez es el docente; ambos llegan a acuerdos igual de sostenibles"]'::jsonb, 1, 'Cuando el docente facilita en vez de juzgar, ambas partes participan activamente en construir la solución, lo cual aumenta la probabilidad de que el acuerdo se sostenga en el tiempo, comparado con una sentencia impuesta desde afuera.', 'lesson'),
('comunicacion-asertiva', 5, '¿En qué tipo de situación la mediación simple entre estudiantes NO es suficiente y requiere una intervención más amplia?', '["Cuando dos estudiantes tienen un desacuerdo puntual sobre un turno de juego","Cuando hay patrones repetidos de agresión, diferencias de poder significativas (como bullying sostenido), o situaciones que involucran seguridad física","Cuando los estudiantes no se ponen de acuerdo en la primera conversación","Cuando los estudiantes son de grados diferentes y no se conocen bien"]'::jsonb, 1, 'Los conflictos con patrones repetidos de agresión, diferencias de poder claras entre las partes, o riesgo de seguridad física requieren una intervención más amplia que una mediación puntual — incluyendo posiblemente a la familia o la dirección del centro.', 'lesson'),
('comunicacion-asertiva', 6, '¿Cuál es una estructura efectiva para dar retroalimentación difícil a la familia de un estudiante sobre su conducta?', '["Empezar directamente con la queja principal, sin rodeos, para no hacer perder tiempo","Empezar con algo positivo genuino sobre el estudiante, describir la conducta específica sin etiquetas, y preguntar cómo pueden apoyarlo juntos","Esperar a acumular varias situaciones para tener evidencia antes de contactar a la familia","Usar un tono de advertencia formal desde el inicio de la conversación"]'::jsonb, 1, 'Esta estructura —positivo genuino, conducta específica sin etiquetas, invitación a colaborar— reduce la defensividad natural de la familia y construye una relación de equipo en vez de una de juicio, aumentando la probabilidad de colaboración real.', 'lesson'),
('comunicacion-asertiva', 7, '¿Por qué aprender a decir "no" de forma respetuosa (poner límites profesionales) es parte de la comunicación asertiva, y no una falta de compromiso?', '["Porque decir \"no\" a tiempo evita tener que dar explicaciones después","Porque un límite claro y respetuoso, con alternativa cuando sea posible, sostiene el bienestar del docente sin dañar la relación, mientras que decir \"sí\" a todo constantemente conduce más rápido al desgaste","Porque la institución valora más a los docentes que ponen límites","Porque decir \"no\" es un derecho del docente y no necesita explicación: basta con negarse a cualquier tarea extra, sin ofrecer alternativas"]'::jsonb, 1, 'La asertividad incluye la capacidad de expresar límites propios de forma clara y respetuosa. Decir "sí" a todo sin límites no es sostenible a largo plazo y conduce con mayor rapidez al desgaste profesional (burnout).', 'lesson'),
('comunicacion-asertiva', 8, 'Un estudiante interrumpe constantemente. Una docente responde: ''Tú siempre interrumpes, eres un irrespetuoso''. ¿Qué estilo es y cuál sería una reformulación asertiva?', '["Estilo agresivo; reformular: ''Cuando hablas mientras explico, me cuesta continuar. Necesito que levantes la mano''.","Estilo pasivo; reformular: ''Bueno, no importa, sigue''.","Estilo asertivo, porque dice claramente lo que piensa.","Estilo agresivo; reformular: ''Si sigues interrumpiendo, tendrás una consecuencia''."]'::jsonb, 0, 'El mensaje en primera persona describe, expresa impacto y pide un cambio.', 'exam'),
('comunicacion-asertiva', 9, 'Un padre llega molesto por la nota de su hija. ¿Qué respuesta refleja mejor la escucha activa?', '["''Entiendo que te preocupa su nota; cuéntame qué has notado para revisarlo juntos.''","''La nota es correcta, no hay nada que discutir; si tiene dudas, puede presentarlas por escrito.''","''Tiene razón, la cambiaré.''","''Hablemos de eso en la próxima reunión de padres.''"]'::jsonb, 0, 'Validar la emoción y escuchar antes de resolver.', 'exam'),
('comunicacion-asertiva', 10, 'Una docente quiere comprobar que entendió a un estudiante alterado. ¿Qué técnica aplica?', '["Aconsejarle de inmediato qué debe hacer.","Decirle que está exagerando, para que pueda ver la situación con más distancia y objetividad.","Parafrasear con sus propias palabras: ''Si te entendí bien, te sentiste excluido del equipo''.","Decirle que todos se sienten así alguna vez."]'::jsonb, 2, 'Parafrasear confirma comprensión.', 'exam'),
('comunicacion-asertiva', 11, 'Dos estudiantes pelean por un material. Un docente decide quién tiene razón en segundos. ¿Qué error del curso comete?', '["Dejar que lo resuelvan solos, sin intervenir.","Quitarles el material a los dos para que dejen de pelear por él en clase.","Pedir al grupo que opine sobre quién tiene razón.","Actuar como juez en lugar de facilitador y resolver sin entender."]'::jsonb, 3, 'El docente es facilitador, no juez.', 'exam'),
('comunicacion-asertiva', 12, 'Una colega te pide que la reemplaces por tercera vez en la semana y no puedes. ¿Qué respuesta asertiva sería adecuada?', '["''Sí, claro'', aunque te perjudique, para mantener la buena relación.","''Ya te he ayudado dos veces esta semana, así que esta vez tendrás que buscar a otra persona.''","''Entiendo que lo necesitas, pero esta vez no puedo; podría ayudarte la próxima semana.''","Decir que lo vas a pensar y no responder."]'::jsonb, 2, 'Decir no con respeto.', 'exam'),
('comunicacion-asertiva', 13, 'Una docente quiere comunicar a una familia una preocupación sobre el rendimiento de su hijo. ¿Qué estructura es más adecuada?', '["Enviar una nota con las calificaciones del periodo y esperar a que la familia solicite una reunión.","Describir todo lo que hace mal para que la familia actúe.","Pedir a la familia que le ponga más tareas en casa.","Empezar con una fortaleza, describir hechos, expresar la preocupación y acordar acciones."]'::jsonb, 3, 'Retroalimentación difícil con hechos y colaboración.', 'exam'),
('comunicacion-asertiva', 14, 'Una docente escribe a un padre: ''Su hijo es muy irresponsable y necesita cambiar ya''. ¿Qué mejoraría el mensaje?', '["Agregar las faltas y retrasos del mes para que el padre vea que no es una exageración.","Enviarlo con copia a la dirección para que tenga más peso.","Describir hechos, mostrar interés por el estudiante y proponer pasos juntos.","Quitar el motivo y solo pedir una reunión sin explicar para qué."]'::jsonb, 2, 'La asertividad por escrito cuida el tono.', 'exam'),
('comunicacion-asertiva', 15, 'Un docente permite que un estudiante interrumpa una y otra vez sin decir nada, pero acumula frustración. ¿Qué estilo de comunicación usa?', '["Asertivo","Pasivo","Agresivo","Facilitador"]'::jsonb, 1, 'El estilo pasivo evita expresar la necesidad propia para no generar tensión; la frustración acumulada suele explotar después.', 'exam'),
('comunicacion-asertiva', 16, '¿Cuál de estas frases es un ''mensaje yo''?', '["''Tú siempre interrumpes la clase.''","''Yo necesito que esperes tu turno para hablar.''","''¿Por qué nunca escuchas cuando estoy hablando?''","''Me parece que eres muy desordenado.''"]'::jsonb, 1, 'El mensaje yo expresa la necesidad propia sin acusar, lo que reduce la defensividad del otro.', 'exam'),
('comunicacion-asertiva', 17, '¿Qué significa que la asertividad no es ''dureza''?', '["Que hay que ceder en lo posible para mantener la armonía del grupo","Que se puede ser firme y cálido a la vez: ''Entiendo que esto te frustra, y aun así necesito que...''","Que no se deben expresar emociones al poner un límite","Que los límites se ponen con voz suave, aunque no se sostengan"]'::jsonb, 1, 'La asertividad combina el límite claro con respeto y calidez; no es frialdad.', 'exam'),
('comunicacion-asertiva', 18, '¿Por qué conviene una pregunta abierta en lugar de una cerrada cuando un estudiante está preocupado?', '["Porque es más rápida de responder","Porque invita a contar más: ''¿Qué es lo que más te preocupa?'' revela más que ''¿Estás bien?''","Porque ayuda a que el estudiante llegue solo a la solución","Porque evita hablar de emociones"]'::jsonb, 1, 'Las preguntas cerradas suelen recibir una palabra; las abiertas abren la conversación.', 'exam'),
('comunicacion-asertiva', 19, 'Haces una pregunta difícil y el estudiante se queda en silencio. ¿Qué recomienda el curso?', '["Hacer otra pregunta de inmediato para no incomodarlo y que la conversación siga fluyendo","Tolerar un silencio breve: suele dar espacio para una respuesta más honesta","Responder tú mismo la pregunta","Cambiar de tema"]'::jsonb, 1, 'El impulso es llenar el silencio, pero unos segundos de espera suelen traer la respuesta más importante.', 'exam'),
('comunicacion-asertiva', 20, '¿Cuándo la mediación entre estudiantes NO es suficiente?', '["Cuando el conflicto es por un malentendido menor entre dos estudiantes que son amigos","Cuando hay agresión repetida o gran diferencia de poder, como en el acoso escolar","Cuando los estudiantes tienen edades distintas","Cuando uno de los estudiantes no quiere hablar al principio"]'::jsonb, 1, 'En casos de acoso o agresión repetida, la mediación entre iguales no basta: se requiere intervención y protocolo institucional.', 'exam'),
('comunicacion-asertiva', 21, 'Una mediación terminó con un acuerdo entre dos estudiantes. ¿Qué paso falta para que se sostenga?', '["Ninguno: el acuerdo ya resolvió todo","Un seguimiento breve unos días después para ver si el acuerdo se está cumpliendo","Informar a todo el grupo del conflicto","Aplicar una sanción a ambos estudiantes para reforzar el acuerdo que acaban de firmar"]'::jsonb, 1, 'Sin seguimiento, los acuerdos tienden a olvidarse. Una revisión breve los sostiene.', 'exam'),
('comunicacion-asertiva', 22, '¿Qué recomienda el curso antes de enviar un correo o mensaje sobre un tema delicado?', '["Enviarlo rápido para no perder el impulso","Releerlo pensando en cómo sonará sin tono de voz, y suavizar lo que suene duro","Enviarlo como audio para que se entienda el tono","Enviarlo siempre con copia a la dirección para respaldarte"]'::jsonb, 1, 'Lo escrito pierde el tono y el lenguaje corporal, y puede leerse más duro de lo que se pretendía.', 'exam'),
('comunicacion-asertiva', 23, 'En una reunión con muchos padres, uno insiste en desviar la conversación hacia su caso particular. ¿Qué respuesta es asertiva?', '["Pedirle con firmeza que guarde silencio y seguir con la agenda","Reconocer su preocupación y proponer tratarla en una reunión individual, manteniendo la agenda","Discutir su caso frente a todos hasta resolverlo, para que el resto de las familias vea que se le atiende","Terminar la reunión antes de tiempo"]'::jsonb, 1, 'Mantener la agenda sin descalificar al padre, ofreciendo un espacio adecuado para su caso, es asertividad en grupo.', 'exam')
